/**
 * Create-only lineage for a facility set. A parent makes the new set an
 * extension of it (the backend merges both compositions); switching
 * "replace" on makes it `inherited`, which pins the slug to the parent's so
 * the new set is what that slug resolves to inside this facility.
import { CheckIcon, TrashIcon, UpdateIcon } from "@radix-ui/react-icons";
import { useMutation } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import {
  FormControl,
  FormField,
  FormItem,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";

import { ValueSetLookupResponse } from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import mutate from "@/Utils/request/mutate";

type CodingFieldProps = {
  system: string;
  name: string;
  form: any;
  className?: string;
  onRemove?: () => void;
  removeDisabled?: boolean;
};

export const CodingField = ({
  system,
  name,
  form,
  className,
  onRemove,
  removeDisabled,
}: CodingFieldProps) => {
  const { t } = useTranslation();
  const {
    mutate: lookup,
    isSuccess: isVerified,
    isPending: isLookupPending,
    reset: resetVerified,
  } = useMutation({
    mutationFn: mutate(valueSetApi.lookup, { silent: true }),
    onSuccess: (response: ValueSetLookupResponse) => {
      if (response.metadata) {
        form.setValue(`${name}.display`, response.metadata.display, {
          shouldValidate: true,
        });
        toast.success(t("code_verified_successfully"));
      }
    },
    onError: () => {
      resetVerified();

      toast.error(t("failed_to_verify_code"));
    },
  });

  const handleVerify = () => {
    const code = form.getValues(`${name}.code`);

    if (!system || !code) {
      toast.error(t("select_system_first"));
      return;
    }

    lookup({ system, code });
  };

  const handleCodeChange = () => {
    resetVerified();
    form.setValue(`${name}.display`, "", { shouldValidate: true });
  };
  return (
    <div className={cn("flex flex-col sm:flex-row gap-2 sm:gap-4", className)}>
      <div className="flex gap-2 items-start flex-1">
        <FormField
          control={form.control}
          name={`${name}.code`}
          render={({ field }) => (
            <FormItem className="flex-1">
              <FormControl>
                <Input
                  {...field}
                  placeholder={t("code")}
                  onChange={(e) => {
                    field.onChange(e);
                    handleCodeChange();
                  }}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <Button
          type="button"
          variant="outline"
          size="icon"
          onClick={isVerified ? undefined : handleVerify}
          disabled={isLookupPending || isVerified}
          className={cn(
            "shrink-0 sm:hidden",
            isVerified
              ? "bg-transparent border-none shadow-none hover:bg-transparent hover:border-none hover:shadow-none"
              : "hover:border-gray-400 hover:bg-gray-100",
          )}
        >
          {isVerified ? (
            <CheckIcon className="size-4 text-green-600 transition-colors duration-300" />
          ) : (
            <UpdateIcon
              className={cn("size-4", isLookupPending && "animate-spin")}
            />
          )}
        </Button>
        {onRemove && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={onRemove}
            disabled={removeDisabled}
            className="shrink-0 sm:hidden"
          >
            <TrashIcon className="size-4" />
          </Button>
        )}
      </div>
      <FormField
        control={form.control}
        name={`${name}.display`}
        render={({ field }) => (
          <FormItem className="flex-1">
            <FormControl>
              <Input
                {...field}
                placeholder={t("unverified")}
                className={!field.value ? "text-gray-500" : ""}
                readOnly
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <Button
        aria-label="Verify code"
        type="button"
        variant="outline"
        size="icon"
        onClick={isVerified ? undefined : handleVerify}
        disabled={isLookupPending || isVerified}
        className={cn(
          "hidden sm:flex shrink-0 items-center",
          isVerified
            ? "bg-transparent border-none shadow-none hover:bg-transparent hover:border-none hover:shadow-none"
            : "hover:border-gray-400 hover:bg-gray-100",
        )}
      >
        {isVerified ? (
          <CheckIcon className="size-4 text-green-600 transition-colors duration-300" />
        ) : (
          <UpdateIcon
            className={cn("size-4", isLookupPending && "animate-spin")}
          />
        )}
      </Button>
      {onRemove && (
        <Button
          type="button"
          variant="ghost"
          size="icon"
          onClick={onRemove}
          disabled={removeDisabled}
          className="hidden sm:flex shrink-0 items-center"
        >
          <TrashIcon className="size-4" />
        </Button>
      )}
    </div>
  );
};

