    resolver: zodResolver(valuesetFormSchema),
    defaultValues: {
      name: initialData?.name || "",
      slug: initialData?.slug || initialParent?.slug || "",
      description: initialData?.description || "",
      status: initialData?.status || ValueSetStatus.ACTIVE,
      is_system_defined: initialData?.is_system_defined || false,
      compose: {
        include:
          initialData?.compose?.include.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
        exclude:
          initialData?.compose?.exclude.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
      },
      parent: initialParent?.id,
      // Customize defaults to replacing the parent — that is the whole
      // point of the flow; a plain extension is the opt-out.
      inherited: !!initialParent,
    },
  });

  const inherited = form.watch("inherited");

  return (
    <Form {...form}>
      <div className="flex justify-end">
        {!initialData?.id && (
          <ValueSetPreview
            valueset={form.watch()}
            trigger={
              <Button variant="outline_primary">
                <CareIcon icon={"l-eye"} className="h-4 w-4" />
                {t("valueset_preview")}
              </Button>
            }
          />
        )}
      </div>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <FormField
          control={form.control}
          name="name"
          disabled={isReadOnly}
          render={({ field }) => (
            <FormItem>
              <FormLabel aria-required>{t("name")}</FormLabel>
              <FormControl>
                <Input
                  {...field}
                  onChange={(e) => {
                    field.onChange(e);
                    if (form.getValues("inherited")) return;
                    form.setValue(
                      "slug",
                      generateSlug(e.target.value, SLUG_MAX),
                      {
                        shouldValidate: true,
                        shouldDirty: false,
                      },
                    );
                  }}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="slug"
          disabled={isReadOnly}
          render={({ field }) => (
            <FormItem>
              <FormLabel aria-required>{t("slug")}</FormLabel>
              <FormControl>
                {/* Locked on the element, not the Controller: a Controller
                    marked disabled drops its value from the submitted data,
                    and the inherited slug still has to reach the backend. */}
                <Input
                  {...field}
                  disabled={isReadOnly || inherited}
                  onChange={(e) => {
                    const sanitizedValue = e.target.value
                      .toLowerCase()
                      .replace(/[^a-z0-9_-]/g, "");
                    form.setValue("slug", sanitizedValue, {
                      shouldValidate: true,
                      shouldDirty: true,
                    });
                  }}
                />
              </FormControl>
              <FormMessage />
              <FormDescription>
                {inherited
                  ? t("replace_parent_slug_locked")
                  : t("slug_format_message")}
              </FormDescription>
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="description"
          disabled={isReadOnly}
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t("description")}</FormLabel>
              <FormControl>
                <Textarea {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="status"
          render={({ field }) => (
            <FormItem>
              <FormLabel aria-required>{t("status")}</FormLabel>
              <Select
                onValueChange={field.onChange}
                defaultValue={field.value}
                disabled={isReadOnly}
              >
                <FormControl>
                  <SelectTrigger ref={field.ref}>
                    <SelectValue placeholder={t("select_status")} />
                  </SelectTrigger>
                </FormControl>
                <SelectContent>
                  {valuesOf(ValueSetStatus).map((status) => (
                    <SelectItem key={status} value={status}>
                      {t(status)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FormMessage />
            </FormItem>
          )}
        />

        {showBasedOn && (
          <BasedOnFields
            facilityId={scope.facilityId}
            form={form}
            parent={parent}
            parentScope={parentScope}
            onParentChange={(next, nextScope) => {
              setParent(next);
              setParentScope(nextScope);
            }}
            disabled={isReadOnly}
          />
        )}

        <div className="space-y-6">
          <RuleFields type="include" form={form} disabled={isReadOnly} />
          <RuleFields type="exclude" form={form} disabled={isReadOnly} />
        </div>
        {isReadOnly && (
          <div className="text-red-600 text-sm flex justify-end">
            {t(
              initialData?.is_system_defined
                ? "saving_is_disabled_for_system_valuesets"
                : "no_permission_to_edit_valueset",
            )}
          </div>
        )}
        <div className="flex gap-2 w-full justify-end">
          <Button
            variant="outline"
            disabled={isSubmitting}
            type="button"
            onClick={() => goBack(scope.basePath)}
          >
            {t("cancel")}
          </Button>

          <Button
            variant="primary"
            type="submit"
            disabled={isReadOnly || isSubmitting || !form.formState.isDirty}
          >
            {isSubmitting ? t("saving") : t("save_valueset")}
          </Button>
        </div>
      </form>
    </Form>
  );
}
      },
    }),
  });

  const valuesets = response?.results || [];

  const renderActions = (valueset: ValueSetRead) => {
    if (source === "instance" && scope.authContext === "facility") {
      // Instance sets are not editable from a facility (the backend
      // reserves them for superusers) — inspect, or customize a copy.
      return (
        <>
          <ValueSetPreview
            valueset={valueset}
            trigger={
              <Button variant="outline" size="sm">
                <Eye className="size-4 mr-0" />
                {t("preview")}
              </Button>
            }
          />
          {canWrite && (
            <Button
              variant="outline"
