        <Alert variant="destructive">
          <AlertDescription>{t("actions_registry_failed")}</AlertDescription>
        </Alert>
      )}

      {registry.isLoading ? (
        <div className="space-y-2">
          <Skeleton className="h-9 w-full" />
          <Skeleton className="h-9 w-2/3" />
