import React from "react";

import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

export interface EmptyStateProps {
  icon?: React.ReactNode;
  title: string;
  description?: string;
  action?: React.ReactNode;
  className?: string;
}

/**
 * Empty state component to display when there is no data to show.
 *
 * @param icon - Optional icon of your choice it can be Lucide Icon or CareIcon
 *               eg. `<CareIcon icon="l-user" className="text-primary size-6" />` or
 *                   `<LucideIcon className="text-primary size-6" />`
 * @param title - The title of the empty state
 * @param description - Optional description providing more context
 * @param action - Optional action element (e.g., button) to prompt user action
 * @param className - Optional additional class names for styling
 */
export function EmptyState({
  icon,
  title,
  description,
  action,
  className,
}: EmptyStateProps) {
  return (
    <Card
      className={cn(
        "flex flex-col items-center justify-center p-6 text-center border-dashed",
        className,
      )}
    >
      {icon && (
        <div className="rounded-full bg-primary/10 p-3 mb-3">{icon}</div>
      )}
      <h3 className="text-lg font-semibold mb-1">{title}</h3>
      {description && <p className="text-sm text-gray-500">{description}</p>}
      {action && <div className="mt-5">{action}</div>}
    </Card>
  );
}
import { ListChecks } from "lucide-react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

interface QuestionsEmptyStateProps {
  /** Secondary line under the "no questions" heading. */
  hint?: string;
  /** Action row (buttons, "or" separators) rendered under the text. */
  children?: React.ReactNode;
  /** Padding/spacing overrides for the dashed container. */
  className?: string;
}

/**
 * The dashed "no questions yet" treatment shared by the create page, the
 * detail overview list and the builder. Deliberately not ui/EmptyState —
 * this Figma treatment (dashed border, primary icon medallion) intentionally
 * differs from that card-styled primitive.
 */
export function QuestionsEmptyState({
  hint,
  children,
  className,
}: QuestionsEmptyStateProps) {
  const { t } = useTranslation();

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-gray-200 bg-gray-50 px-6 py-10 text-center",
        className,
      )}
    >
      <div className="flex size-12 items-center justify-center rounded-full bg-primary/10">
        <ListChecks className="size-6 text-primary" />
      </div>
      <div className="space-y-1">
        <p className="text-sm font-medium text-gray-900">
          {t("no_questions_added_yet")}
        </p>
        {hint && <p className="text-sm text-gray-500">{hint}</p>}
      </div>
      {children}
    </div>
  );
}
import { Plus, Upload } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { QuestionsEmptyState } from "@/components/QuestionnaireV2/shared/QuestionsEmptyState";

/** No-questions state for the builder's editor pane. */
export function BuilderEmptyState({
  onAddFirst,
  onImport,
}: {
  onAddFirst: () => void;
  /** Omitted when the user lacks questionnaire-write — hides the affordance. */
  onImport?: () => void;
}) {
  const { t } = useTranslation();

  return (
    <QuestionsEmptyState className="gap-4 py-16">
      <Button type="button" variant="outline_primary" onClick={onAddFirst}>
        <Plus className="size-4" />
        {t("add_first_question")}
      </Button>
      {onImport && (
        <>
          <div className="flex w-full max-w-xs items-center gap-2 text-xs font-medium uppercase text-gray-400">
            <span className="h-px flex-1 bg-gray-200" />
            {t("or")}
            <span className="h-px flex-1 bg-gray-200" />
          </div>
          <Button type="button" variant="outline" onClick={onImport}>
            <Upload className="size-4" />
            {t("import_questions")}
          </Button>
        </>
      )}
    </QuestionsEmptyState>
  );
}

