  return (
    <section className="overflow-hidden rounded-lg border border-gray-200 bg-gray-50/60">
      <div className="flex items-center justify-between gap-3 border-b border-gray-200 px-3 py-2.5">
        <div className="flex items-center gap-2">
          <h4 className="text-sm font-medium text-gray-900">{t("concepts")}</h4>
