          <Plus className="size-4" />
          {t("add_concept")}
        </Button>
      </div>
      <div className="space-y-3 p-3">
        {fields.length === 0 && (
          <div className="flex min-h-16 items-center justify-center rounded-md border border-dashed border-gray-300 bg-white px-4 text-center text-sm text-gray-500">
