          </div>
        )}

        {fields.map((field, index) => {
          const rule = rules?.[index];
          const systemLabel =
            Object.entries(TERMINOLOGY_SYSTEMS).find(
              ([, value]) => value === rule?.system,
            )?.[0] ?? t("system");
          const subtitle = `${systemLabel} · ${rule?.concept?.length ?? 0} ${t("concepts")} · ${rule?.filter?.length ?? 0} ${t("filters")}`;

          return (
            <CollapsibleSettingsCard
              key={field.id}
              title={`${t("definition")} ${index + 1}`}
              subtitle={subtitle}
              open={openIndex === index}
              onOpenChange={(open) => setOpenIndex(open ? index : null)}
              badge={
                <Button
                  type="button"
                  variant="ghost"
                  variant="ghost"
                  size="icon"
                  aria-label={`${t("remove")} ${title}`}
                  onClick={() => removeRule(index)}
                  disabled={disabled}
                  className="text-gray-500 hover:text-red-600"
                >
                  <Trash2 className="size-4" />
                </Button>
              }
            >
              <div className="space-y-4">
                <div className="grid gap-3 sm:grid-cols-[minmax(0,1.35fr)_minmax(0,0.65fr)]">
                  <FormField
                    control={form.control}
                    name={`compose.${type}.${index}.system`}
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t("system")}</FormLabel>
