              {fields.length}
            </Badge>
          </div>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={addRule}
          disabled={disabled}
          className="w-full bg-white sm:w-auto"
        >
          <Plus className="size-4" />
          {t("add_rule")}
        </Button>
      </div>

      <div className="space-y-3 p-4">
        {fields.length === 0 && (
          <div className="flex min-h-36 flex-col items-center justify-center rounded-lg border border-dashed border-gray-300 bg-gray-50/50 px-5 text-center">
            <CircleDotDashed
              aria-hidden
              className="mb-2 size-5 text-gray-400"
            />
            <p className="text-sm font-medium text-gray-700">
              {t(
                isInclude
                  ? "valueset_include_empty"
                  : "valueset_exclude_empty",
              )}
            </p>
            <p className="mt-1 max-w-sm text-sm text-gray-500">
              {t(
                isInclude
                  ? "valueset_include_empty_hint"
                  : "valueset_exclude_empty_hint",
              )}
            </p>
          </div>
        )}

        {fields.map((field, index) => {
          const rule = rules?.[index];
          const systemLabel =
            Object.entries(TERMINOLOGY_SYSTEMS).find(
              ([, value]) => value === rule?.system,
            )?.[0] ?? t("system");
          const subtitle = `${systemLabel} · ${rule?.concept?.length ?? 0} ${t("concepts")} · ${rule?.filter?.length ?? 0} ${t("filters")}`;

          return (
            <CollapsibleSettingsCard
              key={field.id}
              title={`${t("definition")} ${index + 1}`}
              subtitle={subtitle}
              open={openIndex === index}
              onOpenChange={(open) => setOpenIndex(open ? index : null)}
              badge={
                <Button
                  type="button"
                  variant="ghost"
                  variant="ghost"
                  size="icon"
                  aria-label={`${t("remove")} ${title}`}
                  onClick={() => removeRule(index)}
                  disabled={disabled}
                  className="text-gray-500 hover:text-red-600"
                >
                  <Trash2 className="size-4" />
                </Button>
              }
            >
              <div className="space-y-4">
                <div className="grid gap-3 sm:grid-cols-[minmax(0,1.35fr)_minmax(0,0.65fr)]">
                  <FormField
                    control={form.control}
                    name={`compose.${type}.${index}.system`}
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t("system")}</FormLabel>
                        <Select
                          onValueChange={(system) => {
                            field.onChange(system);
                            const concepts =
                              form.getValues(
                                `compose.${type}.${index}.concept`,
                              ) ?? [];
                            concepts.forEach((_, conceptIndex) => {
                              form.setValue(
                                `compose.${type}.${index}.concept.${conceptIndex}.display`,
                                "",
                                { shouldDirty: true, shouldValidate: true },
                              );
                            });
                          }}
                          value={field.value}
                          disabled={disabled}
                        >
                          <FormControl>
                            <SelectTrigger ref={field.ref}>
                              <SelectValue placeholder={t("select_system")} />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {Object.entries(TERMINOLOGY_SYSTEMS).map(
                              ([key, value]) => (
                                <SelectItem key={key} value={value}>
                                  {key}
                                </SelectItem>
                              ),
                            )}
                          </SelectContent>
                        </Select>
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name={`compose.${type}.${index}.version`}
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>{t("version")}</FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            placeholder={t("version")}
                            disabled={disabled}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>
                <ConceptFields
                  nestIndex={index}
                  type={type}
                  parentForm={form}
                  disabled={disabled}
                />
                <FilterFields
                  nestIndex={index}
                  type={type}
                  disabled={disabled}
                  parentForm={form}
                />
              </div>
            </CollapsibleSettingsCard>
          );
        })}
      </div>
    </section>
  );
}

/**
 * Create-only lineage for a facility set. A parent makes the new set an
 * extension of it (the backend merges both compositions); switching
 * "replace" on makes it `inherited`, which pins the slug to the parent's so
 * the new set is what that slug resolves to inside this facility.
 */
function BasedOnFields({
  facilityId,
  form,
  parent,
  parentScope,
  onParentChange,
  disabled,
}: {
  facilityId: string;
  form: UseFormReturn<ValueSetFormData>;
  parent?: ValueSetRead;
  parentScope: ScopedValueSet["authContext"];
  onParentChange: (
    parent: ValueSetRead | undefined,
    scope: ScopedValueSet["authContext"],
  ) => void;
  disabled?: boolean;
}) {
  const { t } = useTranslation();
  const parentLabelId = useId();
  const authoredSlug = () => generateSlug(form.getValues("name"), SLUG_MAX);

  // Replacing means taking the parent's slug, which inside one facility
  // would collide with a facility parent under the backend's per-facility
  // slug constraint. Only an instance parent can be replaced.
  const canReplace = !!parent && parentScope === "instance";

  const handleParentChange = (
    option: ScopedValueSet | undefined,
    scope = option?.authContext ?? "instance",
  ) => {
    const next = option?.valueset;
    onParentChange(next, scope);
    form.setValue("parent", next?.id, { shouldDirty: true });
    const keepsInherited =
      !!next && scope === "instance" && form.getValues("inherited");
    form.setValue("inherited", keepsInherited, { shouldDirty: true });
    // The slug follows the parent while replacing, and reverts to one
    // authored from the name otherwise — leaving the parent's slug behind
    // on a plain extension would submit a "system-…" slug the backend
    // rejects.
    form.setValue("slug", keepsInherited ? next.slug : authoredSlug(), {
      shouldValidate: true,
    });
  };

  const handleInheritedChange = (checked: boolean) => {
    form.setValue("inherited", checked, { shouldDirty: true });
    form.setValue("slug", checked && parent ? parent.slug : authoredSlug(), {
      shouldValidate: true,
    });
  };

  return (
    <Card className="overflow-hidden shadow-none">
      <CardHeader className="border-b border-gray-100 bg-gray-50/70 p-4">
        <CardTitle className="text-sm font-semibold text-gray-900">
          {t("based_on")}
        </CardTitle>
        <CardDescription>{t("based_on_valueset_hint")}</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4 p-4">
        <div className="space-y-2">
          <Label id={parentLabelId}>{t("parent_value_set")}</Label>
          <ValueSetParentPicker
            facilityId={facilityId}
            value={parent}
            onChange={handleParentChange}
            disabled={disabled}
            aria-labelledby={parentLabelId}
          />
        </div>
        <FormField
          control={form.control}
          name="inherited"
          render={({ field }) => (
            <FormItem className="flex items-start gap-3 space-y-0 rounded-lg border border-gray-200 bg-gray-50/70 p-3.5">
              <FormControl>
                <Switch
                  checked={field.value}
                  onCheckedChange={handleInheritedChange}
                  disabled={disabled || !canReplace}
                />
              </FormControl>
              <div className="space-y-1">
                <FormLabel>{t("replace_parent_in_facility")}</FormLabel>
                <FormDescription>
                  {parent && !canReplace
                    ? t("replace_parent_instance_only")
                    : t("replace_parent_in_facility_hint")}
                </FormDescription>
              </div>
            </FormItem>
          )}
        />
      </CardContent>
    </Card>
  );
}

export function ValueSetForm({
  scope,
  initialData,
  initialParent,
  onSubmit,
  isSubmitting,
  isReadOnly,
  accessControl,
}: ValueSetFormProps) {
  const { t } = useTranslation();
  const [parent, setParent] = useState<ValueSetRead | undefined>(initialParent);
  // The seeded parent always comes from the list's Instance tab, which is
  // the only place Customize is offered.
  const [parentScope, setParentScope] =
    useState<ScopedValueSet["authContext"]>("instance");
  // Lineage is create-only, and only a facility can extend another set.
  const showBasedOn = !initialData && scope.authContext === "facility";

  const conceptSchema = z.object({
    code: z.string().min(1, t("field_required")),
    display: z.string().min(1, t("field_required")),
  });
  const filterSchema = z.object({
    property: z.string().min(1, t("field_required")),
    op: z.string().min(1, t("field_required")),
    value: z.string().min(1, t("field_required")),
  });
  const ruleSchema = z.object({
    system: z.string(),
    version: z.string(),
    concept: z.array(conceptSchema).optional(),
    filter: z.array(filterSchema).optional(),
  });
  const valuesetFormSchema = z
    .object({
      name: z.string().trim().min(1, t("field_required")),
      slug: z.string().trim(),
      description: z.string(),
      status: z.enum([
        ValueSetStatus.ACTIVE,
        ValueSetStatus.DRAFT,
        ValueSetStatus.RETIRED,
        ValueSetStatus.UNKNOWN,
      ]),
      is_system_defined: z.boolean(),
      compose: z.object({
        include: z.array(ruleSchema),
        exclude: z.array(ruleSchema),
      }),
      parent: z.string().optional(),
      inherited: z.boolean(),
    })
    .superRefine((data, ctx) => {
      // These are authoring rules for a NEW slug. They do not apply to a
      // slug the server assigned: an inherited set takes its parent's
      // verbatim, and an existing set keeps its own — several system slugs
      // are longer than SLUG_MAX, and re-validating them here would make
      // those sets impossible to save.
      if (data.inherited || data.slug === initialData?.slug) return;
      if (data.slug.length < SLUG_MIN || data.slug.length > SLUG_MAX) {
        ctx.addIssue({
          code: "custom",
          path: ["slug"],
          message: t("character_count_validation", {
            min: SLUG_MIN,
            max: SLUG_MAX,
          }),
        });
      } else if (!/^[-\w]+$/.test(data.slug)) {
        ctx.addIssue({
          code: "custom",
          path: ["slug"],
          message: t("slug_format_message"),
        });
      }
    });

  const form = useForm<ValueSetFormData>({
    resolver: zodResolver(valuesetFormSchema),
    defaultValues: {
      name: initialData?.name || "",
      slug: initialData?.slug || initialParent?.slug || "",
      description: initialData?.description || "",
      status: initialData?.status || ValueSetStatus.ACTIVE,
      is_system_defined: initialData?.is_system_defined || false,
      compose: {
        include:
          initialData?.compose?.include.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
        exclude:
          initialData?.compose?.exclude.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
      },
      parent: initialParent?.id,
      // Customize defaults to replacing the parent — that is the whole
      // point of the flow; a plain extension is the opt-out.
      inherited: !!initialParent,
    },
  });

  // All fields have complete defaults above; react-hook-form's broad
  // DeepPartial return type does not reflect that runtime guarantee.
  const values = useWatch({ control: form.control }) as ValueSetFormData;
  const inherited = values.inherited;
  const pageTitle = initialData
    ? initialData.is_system_defined
      ? t("preview_value_set")
      : t("edit_value_set")
    : t("create_new_value_set");
  const includeCount = values.compose.include.length;
  const excludeCount = values.compose.exclude.length;

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-5">
        <div className="sticky top-0 z-20 -mx-4 -mt-4 space-y-3 border-b border-gray-200 bg-white/95 px-4 py-3 backdrop-blur-sm sm:-mx-6 sm:-mt-6 sm:px-6">
          <Button
            type="button"
            variant="outline"
            size="xs"
            onClick={() => goBack(scope.basePath)}
          >
            <ArrowLeft className="size-4" />
            {t("back")}
          </Button>

          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div className="flex min-w-0 flex-wrap items-center gap-2">
              <h1 className="text-3xl leading-9 font-bold tracking-tight text-gray-950">
                {pageTitle}
              </h1>
              <Badge variant="outline" className="uppercase">
                {t(scope.authContext)}
              </Badge>
              {isReadOnly && (
                <Badge variant="secondary">{t("read_only")}</Badge>
              )}
            </div>

            <div className="flex flex-wrap items-center gap-2">
              <ValueSetPreview
                valueset={values}
                trigger={
                  <Button type="button" variant="outline_primary">
                    <Eye className="size-4" />
                    {t("valueset_preview")}
                  </Button>
                }
              />
              <Button
                variant="outline"
                disabled={isSubmitting}
                type="button"
                onClick={() => goBack(scope.basePath)}
              >
                {t("cancel")}
              </Button>
              {!isReadOnly && (
                <Button
                  variant="primary"
                  type="submit"
                  disabled={isSubmitting || !form.formState.isDirty}
                >
                  <Save className="size-4" />
                  {isSubmitting ? t("saving") : t("save_valueset")}
                </Button>
              )}
            </div>
          </div>
        </div>

        <div className="grid items-start gap-5 md:grid-cols-[minmax(0,1fr)_280px] md:gap-6">
          <div className="min-w-0 space-y-5">
            <Card className="overflow-hidden shadow-none">
              <CardHeader className="border-b border-gray-100 bg-gray-50/70 p-4">
                <CardTitle>
                  <h2 className="text-xl font-semibold tracking-tight text-gray-900">
                    {t("basic_information")}
                  </h2>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-5 p-4 sm:p-5">
                <FormField
                  control={form.control}
                  name="name"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("name")}</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          disabled={isReadOnly}
                          onChange={(event) => {
                            field.onChange(event);
                            if (
                              initialData ||
                              form.getValues("inherited") ||
                              form.formState.dirtyFields.slug
                            ) {
                              return;
                            }
                            form.setValue(
                              "slug",
                              generateSlug(event.target.value, SLUG_MAX),
                              {
                                shouldValidate: true,
                                shouldDirty: false,
                              },
                            );
                          }}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="slug"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("slug")}</FormLabel>
                      <FormControl>
                        {/* Locked on the element, not the Controller: a
                            disabled Controller drops its value from submitted
                            data, but inherited slugs still reach the backend. */}
                        <Input
                          {...field}
                          disabled={isReadOnly || inherited}
                          className="font-mono text-sm"
                          onChange={(event) => {
                            const sanitizedValue = event.target.value
                              .toLowerCase()
                              .replace(/[^a-z0-9_-]/g, "");
                            form.setValue("slug", sanitizedValue, {
                              shouldValidate: true,
                              shouldDirty: true,
                            });
                          }}
                        />
                      </FormControl>
                      <FormMessage />
                      <FormDescription>
                        {inherited
                          ? t("replace_parent_slug_locked")
                          : t("slug_format_message")}
                      </FormDescription>
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{t("description")}</FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          disabled={isReadOnly}
                          className="min-h-28 resize-y"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>

            {accessControl && (
              <Card className="shadow-none">
                <CardContent className="p-4 sm:p-5">
                  {accessControl}
                </CardContent>
import { useQuery } from "@tanstack/react-query";
import { CircleDotDashed, CircleMinus, CirclePlus, Search } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import Autocomplete from "@/components/ui/autocomplete";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";

import { ValueSetBase } from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";
import { mergeAutocompleteOptions } from "@/Utils/utils";

interface ValueSetPreviewProps {
  valueset: ValueSetBase;
  trigger: React.ReactNode;
}

export function ValueSetPreview({ valueset, trigger }: ValueSetPreviewProps) {
  const [open, setOpen] = useState(false);
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState("");
  const hasDefinition = [
    ...valueset.compose.include,
    ...valueset.compose.exclude,
  ].some((rule) => !!rule.system);

  const { data: searchQuery, isFetching } = useQuery({
    queryKey: ["valueset", "previewSearch", search, valueset.compose],
    queryFn: query.debounced(valueSetApi.previewSearch, {
      queryParams: { search, count: 20 },
      body: {
        ...valueset,
        name: valueset.name || "Preview",
        slug: valueset.slug || "preview-slug",
      },
    }),
    enabled: open && hasDefinition,
  });

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger asChild>{trigger}</SheetTrigger>
      <SheetContent className="w-full p-0 sm:max-w-xl">
        <SheetHeader className="space-y-1 border-b border-gray-200 bg-gray-50/80 p-5 text-left sm:p-6">
          <SheetTitle className="text-xl font-semibold">
            {t("valueset_preview")}
          </SheetTitle>
          <SheetDescription>
            {t("valueset_preview_description")}
          </SheetDescription>
        </SheetHeader>
        <div className="space-y-5 p-5 sm:p-6">
          <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-xs">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div className="min-w-0">
                <p className="truncate font-semibold text-gray-950">
                  {valueset.name || t("value_set")}
                </p>
                {valueset.slug && (
                  <code className="mt-1 block truncate text-xs text-gray-500">
                    {valueset.slug}
                  </code>
                )}
              </div>
              <Badge variant="secondary">{t(valueset.status)}</Badge>
            </div>
            <div className="mt-4 grid grid-cols-2 gap-2">
              <div className="flex items-center justify-between rounded-lg border border-primary-200 bg-primary-100/50 px-3 py-2 text-sm text-primary-900">
                <span className="flex items-center gap-2">
                  <CirclePlus aria-hidden className="size-4" />
                  {t("include_rules")}
                </span>
                <span className="font-semibold tabular-nums">
                  {valueset.compose.include.length}
                </span>
              </div>
              <div className="flex items-center justify-between rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-900">
                <span className="flex items-center gap-2">
                  <CircleMinus aria-hidden className="size-4" />
                  {t("exclude_rules")}
                </span>
                <span className="font-semibold tabular-nums">
                  {valueset.compose.exclude.length}
                </span>
              </div>
            </div>
          </div>

          {hasDefinition ? (
            <div className="space-y-2">
              <Label className="flex items-center gap-2">
                <Search aria-hidden className="size-4 text-gray-500" />
                {t("search_concept")}
              </Label>
              <Autocomplete
                options={mergeAutocompleteOptions(
                  searchQuery?.results?.map((option) => ({
                    label: option.display || "",
                    value: option.code,
                  })) ?? [],
                )}
                value={selected}
                onChange={setSelected}
                onSearch={setSearch}
                placeholder={t("search_concept")}
                noOptionsMessage={
                  searchQuery && !isFetching
                    ? t("no_results_found")
                    : t("searching")
                }
              />
            </div>
          ) : (
            <div className="flex min-h-44 flex-col items-center justify-center rounded-xl border border-dashed border-gray-300 bg-gray-50/60 p-6 text-center">
              <CircleDotDashed
                aria-hidden
                className="mb-3 size-6 text-gray-400"
              />
              <p className="text-sm font-medium text-gray-800">
                {t("no_data_found")}
              </p>
              <p className="mt-1 max-w-sm text-sm text-gray-500">
                {t("valueset_preview_empty")}
              </p>
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

