interface ValueSetPreviewProps {
  valueset: ValueSetBase;
  trigger: React.ReactNode;
}

export function ValueSetPreview({ valueset, trigger }: ValueSetPreviewProps) {
  const [open, setOpen] = useState(false);
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState("");
  const hasDefinition = [
    ...valueset.compose.include,
    ...valueset.compose.exclude,
  ].some((rule) => !!rule.system);

  const { data: searchQuery, isFetching } = useQuery({
    queryKey: ["valueset", "previewSearch", search, valueset.compose],
    queryFn: query.debounced(valueSetApi.previewSearch, {
      queryParams: { search, count: 20 },
      body: {
        ...valueset,
        name: valueset.name || "Preview",
        slug: valueset.slug || "preview-slug",
      },
    }),
    enabled: open && hasDefinition,
  });

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger asChild>{trigger}</SheetTrigger>
      <SheetContent className="w-full p-0 sm:max-w-xl">
        <SheetHeader className="space-y-1 border-b border-gray-200 bg-gray-50/80 p-5 text-left sm:p-6">
          <SheetTitle className="text-xl font-semibold">
            {t("valueset_preview")}
          </SheetTitle>
          <SheetDescription>
            {t("valueset_preview_description")}
          </SheetDescription>
        </SheetHeader>
        <div className="space-y-5 p-5 sm:p-6">
          <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-xs">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div className="min-w-0">
                <p className="truncate font-semibold text-gray-950">
                  {valueset.name || t("value_set")}
                </p>
                {valueset.slug && (
                  <code className="mt-1 block truncate text-xs text-gray-500">
                    {valueset.slug}
                  </code>
                )}
              </div>
              <Badge variant="secondary">{t(valueset.status)}</Badge>
            </div>
            <div className="mt-4 grid grid-cols-2 gap-2">
              <div className="flex items-center justify-between rounded-lg border border-primary-200 bg-primary-100/50 px-3 py-2 text-sm text-primary-900">
                <span className="flex items-center gap-2">
                  <CirclePlus aria-hidden className="size-4" />
                  {t("include_rules")}
                </span>
                <span className="font-semibold tabular-nums">
                  {valueset.compose.include.length}
                </span>
              </div>
              <div className="flex items-center justify-between rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-900">
                <span className="flex items-center gap-2">
                  <CircleMinus aria-hidden className="size-4" />
                  {t("exclude_rules")}
                </span>
                <span className="font-semibold tabular-nums">
                  {valueset.compose.exclude.length}
                </span>
              </div>
            </div>
          </div>

          {hasDefinition ? (
            <div className="space-y-2">
              <Label className="flex items-center gap-2">
                <Search aria-hidden className="size-4 text-gray-500" />
                {t("search_concept")}
              </Label>
              <Autocomplete
                options={mergeAutocompleteOptions(
                  searchQuery?.results?.map((option) => ({
                    label: option.display || "",
                    value: option.code,
                  })) ?? [],
                )}
                value={selected}
                onChange={setSelected}
                onSearch={setSearch}
                placeholder={t("search_concept")}
                noOptionsMessage={
                  searchQuery && !isFetching
                    ? t("no_results_found")
                    : t("searching")
                }
              />
            </div>
          ) : (
            <div className="flex min-h-44 flex-col items-center justify-center rounded-xl border border-dashed border-gray-300 bg-gray-50/60 p-6 text-center">
              <CircleDotDashed
                aria-hidden
                className="mb-3 size-6 text-gray-400"
              />
              <p className="text-sm font-medium text-gray-800">
                {t("no_data_found")}
              </p>
              <p className="mt-1 max-w-sm text-sm text-gray-500">
                {t("valueset_preview_empty")}
              </p>
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

