514	/**
515	 * Create-only lineage for a facility set. A parent makes the new set an
516	 * extension of it (the backend merges both compositions); switching
517	 * "replace" on makes it `inherited`, which pins the slug to the parent's so
518	 * the new set is what that slug resolves to inside this facility.
519	 */
520	function BasedOnFields({
521	  facilityId,
522	  form,
523	  parent,
524	  parentScope,
525	  onParentChange,
526	  disabled,
527	}: {
528	  facilityId: string;
529	  form: UseFormReturn<ValueSetFormData>;
530	  parent?: ValueSetRead;
531	  parentScope: ScopedValueSet["authContext"];
532	  onParentChange: (
533	    parent: ValueSetRead | undefined,
534	    scope: ScopedValueSet["authContext"],
535	  ) => void;
536	  disabled?: boolean;
537	}) {
538	  const { t } = useTranslation();
539	  const parentLabelId = useId();
540	  const authoredSlug = () => generateSlug(form.getValues("name"), SLUG_MAX);
541	
542	  // Replacing means taking the parent's slug, which inside one facility
543	  // would collide with a facility parent under the backend's per-facility
544	  // slug constraint. Only an instance parent can be replaced.
545	  const canReplace = !!parent && parentScope === "instance";
546	
547	  const handleParentChange = (
548	    option: ScopedValueSet | undefined,
549	    scope = option?.authContext ?? "instance",
550	  ) => {
551	    const next = option?.valueset;
552	    onParentChange(next, scope);
553	    form.setValue("parent", next?.id, { shouldDirty: true });
554	    const keepsInherited =
555	      !!next && scope === "instance" && form.getValues("inherited");
556	    form.setValue("inherited", keepsInherited, { shouldDirty: true });
557	    // The slug follows the parent while replacing, and reverts to one
558	    // authored from the name otherwise — leaving the parent's slug behind
559	    // on a plain extension would submit a "system-…" slug the backend
560	    // rejects.
561	    form.setValue("slug", keepsInherited ? next.slug : authoredSlug(), {
562	      shouldValidate: true,
563	    });
564	  };
565	
566	  const handleInheritedChange = (checked: boolean) => {
567	    form.setValue("inherited", checked, { shouldDirty: true });
568	    form.setValue("slug", checked && parent ? parent.slug : authoredSlug(), {
569	      shouldValidate: true,
570	    });
571	  };
572	
573	  return (
574	    <Card className="overflow-hidden shadow-none">
575	      <CardHeader className="border-b border-gray-100 bg-gray-50/70 p-4">
576	        <CardTitle className="text-sm font-semibold text-gray-900">
577	          {t("based_on")}
578	        </CardTitle>
579	        <CardDescription>{t("based_on_valueset_hint")}</CardDescription>
580	      </CardHeader>
581	      <CardContent className="space-y-4 p-4">
582	        <div className="space-y-2">
583	          <Label id={parentLabelId}>{t("parent_value_set")}</Label>
584	          <ValueSetParentPicker
585	            facilityId={facilityId}
586	            value={parent}
587	            onChange={handleParentChange}
588	            disabled={disabled}
589	            aria-labelledby={parentLabelId}
590	          />
591	        </div>
592	        <FormField
593	          control={form.control}
594	          name="inherited"
595	          render={({ field }) => (
596	            <FormItem className="flex items-start gap-3 space-y-0 rounded-lg border border-gray-200 bg-gray-50/70 p-3.5">
597	              <FormControl>
598	                <Switch
599	                  checked={field.value}
600	                  onCheckedChange={handleInheritedChange}
601	                  disabled={disabled || !canReplace}
602	                />
603	              </FormControl>
604	              <div className="space-y-1">
605	                <FormLabel>{t("replace_parent_in_facility")}</FormLabel>
606	                <FormDescription>
607	                  {parent && !canReplace
608	                    ? t("replace_parent_instance_only")
609	                    : t("replace_parent_in_facility_hint")}
610	                </FormDescription>
611	              </div>
612	            </FormItem>
613	          )}
614	        />
615	      </CardContent>
616	    </Card>
617	  );
618	}
