631	  // The seeded parent always comes from the list's Instance tab, which is
632	  // the only place Customize is offered.
633	  const [parentScope, setParentScope] =
634	    useState<ScopedValueSet["authContext"]>("instance");
635	  // Lineage is create-only, and only a facility can extend another set.
636	  const showBasedOn = !initialData && scope.authContext === "facility";
637	
638	  const conceptSchema = z.object({
639	    code: z.string().min(1, t("field_required")),
640	    display: z.string().min(1, t("field_required")),
641	  });
642	  const filterSchema = z.object({
643	    property: z.string().min(1, t("field_required")),
644	    op: z.string().min(1, t("field_required")),
645	    value: z.string().min(1, t("field_required")),
646	  });
647	  const ruleSchema = z.object({
648	    system: z.string(),
649	    version: z.string(),
650	    concept: z.array(conceptSchema).optional(),
651	    filter: z.array(filterSchema).optional(),
652	  });
653	  const valuesetFormSchema = z
654	    .object({
655	      name: z.string().trim().min(1, t("field_required")),
656	      slug: z.string().trim(),
657	      description: z.string(),
658	      status: z.enum([
659	        ValueSetStatus.ACTIVE,
