673	      // These are authoring rules for a NEW slug. They do not apply to a
674	      // slug the server assigned: an inherited set takes its parent's
675	      // verbatim, and an existing set keeps its own — several system slugs
676	      // are longer than SLUG_MAX, and re-validating them here would make
677	      // those sets impossible to save.
678	      if (data.inherited || data.slug === initialData?.slug) return;
679	      if (data.slug.length < SLUG_MIN || data.slug.length > SLUG_MAX) {
680	        ctx.addIssue({
681	          code: "custom",
