620	export function ValueSetForm({
621	  scope,
622	  initialData,
623	  initialParent,
624	  onSubmit,
625	  isSubmitting,
626	  isReadOnly,
627	  accessControl,
628	}: ValueSetFormProps) {
629	  const { t } = useTranslation();
630	  const [parent, setParent] = useState<ValueSetRead | undefined>(initialParent);
631	  // The seeded parent always comes from the list's Instance tab, which is
632	  // the only place Customize is offered.
633	  const [parentScope, setParentScope] =
634	    useState<ScopedValueSet["authContext"]>("instance");
635	  // Lineage is create-only, and only a facility can extend another set.
636	  const showBasedOn = !initialData && scope.authContext === "facility";
637	
638	  const conceptSchema = z.object({
639	    code: z.string().min(1, t("field_required")),
640	    display: z.string().min(1, t("field_required")),
641	  });
642	  const filterSchema = z.object({
643	    property: z.string().min(1, t("field_required")),
644	    op: z.string().min(1, t("field_required")),
645	    value: z.string().min(1, t("field_required")),
646	  });
647	  const ruleSchema = z.object({
648	    system: z.string(),
649	    version: z.string(),
650	    concept: z.array(conceptSchema).optional(),
651	    filter: z.array(filterSchema).optional(),
652	  });
653	  const valuesetFormSchema = z
654	    .object({
655	      name: z.string().trim().min(1, t("field_required")),
656	      slug: z.string().trim(),
657	      description: z.string(),
658	      status: z.enum([
659	        ValueSetStatus.ACTIVE,
660	        ValueSetStatus.DRAFT,
661	        ValueSetStatus.RETIRED,
662	        ValueSetStatus.UNKNOWN,
663	      ]),
664	      is_system_defined: z.boolean(),
665	      compose: z.object({
666	        include: z.array(ruleSchema),
667	        exclude: z.array(ruleSchema),
668	      }),
669	      parent: z.string().optional(),
670	      inherited: z.boolean(),
671	    })
672	    .superRefine((data, ctx) => {
673	      // These are authoring rules for a NEW slug. They do not apply to a
674	      // slug the server assigned: an inherited set takes its parent's
675	      // verbatim, and an existing set keeps its own — several system slugs
676	      // are longer than SLUG_MAX, and re-validating them here would make
677	      // those sets impossible to save.
678	      if (data.inherited || data.slug === initialData?.slug) return;
679	      if (data.slug.length < SLUG_MIN || data.slug.length > SLUG_MAX) {
680	        ctx.addIssue({
681	          code: "custom",
682	          path: ["slug"],
683	          message: t("character_count_validation", {
684	            min: SLUG_MIN,
685	            max: SLUG_MAX,
686	          }),
687	        });
688	      } else if (!/^[-\w]+$/.test(data.slug)) {
689	        ctx.addIssue({
690	          code: "custom",
691	          path: ["slug"],
692	          message: t("slug_format_message"),
693	        });
694	      }
695	    });
