import { useMutation } from "@tanstack/react-query";
import { CheckCircle2, LoaderCircle, SearchCheck, Trash2 } from "lucide-react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";

import { ValueSetLookupResponse } from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import mutate from "@/Utils/request/mutate";

type CodingFieldProps = {
  system: string;
  name: string;
  form: any;
  className?: string;
  onRemove?: () => void;
  removeDisabled?: boolean;
};

export const CodingField = ({
  system,
  name,
  form,
  className,
  onRemove,
  removeDisabled,
}: CodingFieldProps) => {
  const { t } = useTranslation();
  const {
    mutate: lookup,
    isSuccess: isVerified,
    isPending: isLookupPending,
    reset: resetVerified,
  } = useMutation({
    mutationFn: mutate(valueSetApi.lookup, { silent: true }),
    onSuccess: (response: ValueSetLookupResponse) => {
      if (response.metadata) {
        form.setValue(`${name}.display`, response.metadata.display, {
          shouldValidate: true,
        });
        toast.success(t("code_verified_successfully"));
      }
    },
    onError: () => {
      resetVerified();

      toast.error(t("failed_to_verify_code"));
    },
  });

  const handleVerify = () => {
    const code = form.getValues(`${name}.code`);

    if (!system || !code) {
      toast.error(t("select_system_first"));
      return;
    }

    lookup({ system, code });
  };

  const handleCodeChange = () => {
    resetVerified();
    form.setValue(`${name}.display`, "", { shouldValidate: true });
  };
  return (
    <div
      className={cn(
        "grid gap-2 sm:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)_auto_auto] sm:items-start",
        className,
      )}
    >
      <FormField
        control={form.control}
        name={`${name}.code`}
        render={({ field }) => (
          <FormItem>
            <FormLabel className="sr-only">{t("code")}</FormLabel>
            <FormControl>
              <Input
                {...field}
                placeholder={t("code")}
                onChange={(event) => {
                  field.onChange(event);
                  handleCodeChange();
                }}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <FormField
        control={form.control}
        name={`${name}.display`}
        render={({ field }) => (
          <FormItem>
            <FormLabel className="sr-only">{t("unverified")}</FormLabel>
            <FormControl>
              <Input
                {...field}
                placeholder={t("unverified")}
                className={cn("bg-gray-50", !field.value && "text-gray-500")}
                readOnly
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <div className="flex justify-end gap-2 sm:contents">
        <Button
          aria-label={`${t("verify")} ${t("code").toLocaleLowerCase()}`}
          type="button"
          variant="outline"
          size="sm"
          onClick={isVerified ? undefined : handleVerify}
          disabled={isLookupPending || isVerified}
          className={cn(
            "shrink-0 bg-white",
            isVerified
              ? "border-primary-200 bg-primary-100/60 text-primary-800 opacity-100"
              : "hover:border-gray-400 hover:bg-gray-100",
          )}
        >
          {isVerified ? (
            <>
              <CheckCircle2 className="size-4" />
              <span className="hidden lg:inline">{t("code_verified")}</span>
            </>
          ) : (
            <>
              {isLookupPending ? (
                <LoaderCircle className="size-4 animate-spin" />
              ) : (
                <SearchCheck className="size-4" />
              )}
              <span className="hidden lg:inline">{t("verify")}</span>
            </>
          )}
        </Button>
        {onRemove && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label={t("remove")}
            onClick={onRemove}
            disabled={removeDisabled}
            className="shrink-0 text-gray-500 hover:text-red-600"
          >
            <Trash2 className="size-4" />
          </Button>
        )}
      </div>
    </div>
  );
};
import { useQuery } from "@tanstack/react-query";
import { CircleDotDashed, CircleMinus, CirclePlus, Search } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import Autocomplete from "@/components/ui/autocomplete";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";

import { ValueSetBase } from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";
import { mergeAutocompleteOptions } from "@/Utils/utils";

interface ValueSetPreviewProps {
  valueset: ValueSetBase;
  trigger: React.ReactNode;
}

export function ValueSetPreview({ valueset, trigger }: ValueSetPreviewProps) {
  const [open, setOpen] = useState(false);
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState("");
  const hasDefinition = [
    ...valueset.compose.include,
    ...valueset.compose.exclude,
  ].some((rule) => !!rule.system);

  const { data: searchQuery, isFetching } = useQuery({
    queryKey: ["valueset", "previewSearch", search, valueset.compose],
    queryFn: query.debounced(valueSetApi.previewSearch, {
      queryParams: { search, count: 20 },
      body: {
        ...valueset,
        name: valueset.name || "Preview",
        slug: valueset.slug || "preview-slug",
      },
    }),
    enabled: open && hasDefinition,
  });

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger asChild>{trigger}</SheetTrigger>
      <SheetContent className="w-full p-0 sm:max-w-xl">
        <SheetHeader className="space-y-1 border-b border-gray-200 bg-gray-50/80 p-5 text-left sm:p-6">
          <SheetTitle className="text-xl font-semibold">
            {t("valueset_preview")}
          </SheetTitle>
          <SheetDescription>
            {t("valueset_preview_description")}
          </SheetDescription>
        </SheetHeader>
        <div className="space-y-5 p-5 sm:p-6">
          <div className="rounded-xl border border-gray-200 bg-white p-4 shadow-xs">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div className="min-w-0">
                <p className="truncate font-semibold text-gray-950">
                  {valueset.name || t("value_set")}
                </p>
                {valueset.slug && (
                  <code className="mt-1 block truncate text-xs text-gray-500">
                    {valueset.slug}
                  </code>
                )}
              </div>
              <Badge variant="secondary">{t(valueset.status)}</Badge>
            </div>
            <div className="mt-4 grid grid-cols-2 gap-2">
              <div className="flex items-center justify-between rounded-lg border border-primary-200 bg-primary-100/50 px-3 py-2 text-sm text-primary-900">
                <span className="flex items-center gap-2">
                  <CirclePlus aria-hidden className="size-4" />
                  {t("include_rules")}
                </span>
                <span className="font-semibold tabular-nums">
                  {valueset.compose.include.length}
                </span>
              </div>
              <div className="flex items-center justify-between rounded-lg border border-gray-200 bg-gray-100/80 px-3 py-2 text-sm text-gray-800">
                <span className="flex items-center gap-2">
                  <CircleMinus aria-hidden className="size-4" />
                  {t("exclude_rules")}
                </span>
                <span className="font-semibold tabular-nums">
                  {valueset.compose.exclude.length}
                </span>
              </div>
            </div>
          </div>

          {hasDefinition ? (
            <div className="space-y-2">
              <Label className="flex items-center gap-2">
                <Search aria-hidden className="size-4 text-gray-500" />
                {t("search_concept")}
              </Label>
              <Autocomplete
                options={mergeAutocompleteOptions(
                  searchQuery?.results?.map((option) => ({
                    label: option.display || "",
                    value: option.code,
                  })) ?? [],
                )}
                value={selected}
                onChange={setSelected}
                onSearch={setSearch}
                placeholder={t("search_concept")}
                noOptionsMessage={
                  searchQuery && !isFetching
                    ? t("no_results_found")
                    : t("searching")
                }
              />
            </div>
          ) : (
            <div className="flex min-h-44 flex-col items-center justify-center rounded-xl border border-dashed border-gray-300 bg-gray-50/60 p-6 text-center">
              <CircleDotDashed
                aria-hidden
                className="mb-3 size-6 text-gray-400"
              />
              <p className="text-sm font-medium text-gray-800">
                {t("no_data_found")}
              </p>
              <p className="mt-1 max-w-sm text-sm text-gray-500">
                {t("valueset_preview_empty")}
              </p>
            </div>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}
