import { useMutation } from "@tanstack/react-query";
import { CheckCircle2, LoaderCircle, SearchCheck, Trash2 } from "lucide-react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";

import { ValueSetLookupResponse } from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import mutate from "@/Utils/request/mutate";

type CodingFieldProps = {
  system: string;
  name: string;
  form: any;
  className?: string;
  onRemove?: () => void;
  removeDisabled?: boolean;
};

export const CodingField = ({
  system,
  name,
  form,
  className,
  onRemove,
  removeDisabled,
}: CodingFieldProps) => {
  const { t } = useTranslation();
  const {
    mutate: lookup,
    isSuccess: isVerified,
    isPending: isLookupPending,
    reset: resetVerified,
  } = useMutation({
    mutationFn: mutate(valueSetApi.lookup, { silent: true }),
    onSuccess: (response: ValueSetLookupResponse) => {
      if (response.metadata) {
        form.setValue(`${name}.display`, response.metadata.display, {
          shouldValidate: true,
        });
        toast.success(t("code_verified_successfully"));
      }
    },
    onError: () => {
      resetVerified();

      toast.error(t("failed_to_verify_code"));
    },
  });

  const handleVerify = () => {
    const code = form.getValues(`${name}.code`);

    if (!system || !code) {
      toast.error(t("select_system_first"));
      return;
    }

    lookup({ system, code });
  };

  const handleCodeChange = () => {
    resetVerified();
    form.setValue(`${name}.display`, "", { shouldValidate: true });
  };
  return (
    <div
      className={cn(
        "grid gap-2 sm:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)_auto_auto] sm:items-start",
        className,
      )}
    >
      <FormField
        control={form.control}
        name={`${name}.code`}
        render={({ field }) => (
          <FormItem>
            <FormLabel className="sr-only">{t("code")}</FormLabel>
            <FormControl>
              <Input
                {...field}
                placeholder={t("code")}
                onChange={(event) => {
                  field.onChange(event);
                  handleCodeChange();
                }}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <FormField
        control={form.control}
        name={`${name}.display`}
        render={({ field }) => (
          <FormItem>
            <FormLabel className="sr-only">{t("unverified")}</FormLabel>
            <FormControl>
              <Input
                {...field}
                placeholder={t("unverified")}
                className={cn("bg-gray-50", !field.value && "text-gray-500")}
                readOnly
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <div className="flex justify-end gap-2 sm:contents">
        <Button
          aria-label={`${t("verify")} ${t("code").toLocaleLowerCase()}`}
          type="button"
          variant="outline"
          size="sm"
          onClick={isVerified ? undefined : handleVerify}
          disabled={isLookupPending || isVerified}
          className={cn(
            "shrink-0 bg-white",
            isVerified
              ? "border-primary-200 bg-primary-100/60 text-primary-800 opacity-100"
              : "hover:border-gray-400 hover:bg-gray-100",
          )}
        >
          {isVerified ? (
            <>
              <CheckCircle2 className="size-4" />
              <span className="hidden lg:inline">{t("code_verified")}</span>
            </>
          ) : (
            <>
              {isLookupPending ? (
                <LoaderCircle className="size-4 animate-spin" />
              ) : (
                <SearchCheck className="size-4" />
              )}
              <span className="hidden lg:inline">{t("verify")}</span>
            </>
          )}
        </Button>
        {onRemove && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label={t("remove")}
            onClick={onRemove}
            disabled={removeDisabled}
            className="shrink-0 text-gray-500 hover:text-red-600"
          >
            <Trash2 className="size-4" />
          </Button>
        )}
      </div>
    </div>
  );
};
