              </div>
              <div className="grid items-start gap-5">
                <RuleFields type="include" form={form} disabled={isReadOnly} />
                <RuleFields type="exclude" form={form} disabled={isReadOnly} />
              </div>
            </section>
          </div>

          <aside className="order-first h-fit space-y-4 rounded-lg border border-gray-200 bg-white p-4 md:order-last md:sticky md:top-6 md:rounded-none md:border-0 md:bg-transparent md:p-0 lg:top-32">
            <h2 className="text-xl font-semibold tracking-tight text-gray-900">
