import { useQuery } from "@tanstack/react-query";
import { t } from "i18next";
import { useEffect, useState } from "react";

import CareIcon from "@/CAREUI/icons/CareIcon";

import Autocomplete from "@/components/ui/autocomplete";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";

import {
  scopedOptionLabel,
  useScopedValueSets,
} from "@/components/ValueSet/useScopedValueSets";
import { ValueSetEditor } from "@/components/ValueSet/ValueSetEditor";

import {
  INSTANCE_VALUESET_SCOPE,
  ValueSetConfig,
  ValueSetRead,
  ValueSetScope,
  valueSetBinding,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";
import { mergeAutocompleteOptions } from "@/Utils/utils";

interface CreateValueSetProps {
  onValueSetChange?: (valueSet: ValueSetConfig) => void;
  value?: ValueSetConfig;
  /** Where the host is mounted. Inside a facility the picker lists that
   *  facility's sets alongside the instance ones, and the inline "Create
   *  value set" sheet files under the facility — only superusers may
   *  create instance-context sets. */
  scope?: ValueSetScope;
}

export function SelectOrCreateValueset({
  onValueSetChange,
  value,
  scope = INSTANCE_VALUESET_SCOPE,
}: CreateValueSetProps) {
  const [isSheetOpen, setIsSheetOpen] = useState(false);
  const [currentValueSet, setCurrentValueSet] = useState<ValueSetRead>();
  const [searchQuery, setSearchQuery] = useState("");

  const { options, isFetching: isFetchingValuesets } = useScopedValueSets({
    facilityId: scope.facilityId,
    search: searchQuery,
  });

  // An imported questionnaire may reference a valueset by slug alone, and
  // expand_slug is the only endpoint that maps one back to its valueset.
  const { data: valuesetById, isLoading: isLoadingById } = useQuery({
    queryKey: ["valueset", value?.external_id],
    queryFn: query(valueSetApi.get, {
      pathParams: { id: value?.external_id ?? "" },
    }),
    enabled: !!value?.external_id,
  });

  // Slug-only references are instance-level by contract (see
  // valueSetBinding), so this resolves without a facility on purpose.
  const { data: valuesetBySlug, isLoading: isLoadingBySlug } = useQuery({
    queryKey: ["valueset", "by-slug", value?.slug],
    queryFn: query(valueSetApi.expandSlug, {
      body: { slug: value?.slug ?? "", search: "", count: 1 },
    }),
    enabled: !value?.external_id && !!value?.slug,
  });

  const isLoadingCurrent = isLoadingById || isLoadingBySlug;

  useEffect(() => {
    const resolved = valuesetById ?? valuesetBySlug?.valueset;
    resolved && setCurrentValueSet(resolved);
  }, [valuesetById, valuesetBySlug]);

  // The scope suffix is only meaningful where the two lists are merged —
  // an instance set and a facility override of it usually share a name.
  const valueSetOptions = options.map((option) => ({
    label:
      scope.authContext === "facility"
        ? scopedOptionLabel(option, t)
        : option.valueset.name,
    value: option.valueset.id,
  }));

  const handleValueSetChange = (selectedId: string) => {
    const selected = options.find(
      (option) => option.valueset.id === selectedId,
    );
    if (selected) {
      // Show the pick immediately. An instance set is stored by slug alone,
      // so `value.external_id` is empty and the trigger would otherwise keep
      // displaying the previous set until expand_slug resolves.
      setCurrentValueSet(selected.valueset);
      onValueSetChange?.(
        valueSetBinding(selected.valueset, selected.authContext),
      );
      return;
    }
    // Re-picking the current (merged-in) entry keeps the stored reference
    // as is — its binding was decided when it was first chosen.
    if (currentValueSet?.id === selectedId && value) {
      onValueSetChange?.(value);
    }
  };

  return (
    <div className="space-y-1.5">
      <div className="flex items-center gap-2 flex-col sm:flex-row">
        <div className="w-full">
          <Autocomplete
            options={mergeAutocompleteOptions(
              valueSetOptions,
              // No scope suffix: a set resolved from the stored reference
              // carries no auth_context, and guessing from `external_id`
              // mislabels instance sets that older questionnaires pinned.
              currentValueSet
                ? { label: currentValueSet.name, value: currentValueSet.id }
                : undefined,
            )}
            value={value?.external_id ?? currentValueSet?.id ?? ""}
            onChange={handleValueSetChange}
            onSearch={setSearchQuery}
            placeholder={t("select_a_value_set")}
            isLoading={isFetchingValuesets || isLoadingCurrent}
            noOptionsMessage={t("no_valuesets_found")}
          />
        </div>
        <Sheet open={isSheetOpen} onOpenChange={setIsSheetOpen}>
          <SheetTrigger asChild>
            <Button variant="outline" className="gap-2 w-full sm:w-auto">
              <CareIcon icon="l-plus" />
              {t("create_valueset")}
            </Button>
          </SheetTrigger>
          <SheetContent
            side="right"
            className="w-full sm:max-w-2xl overflow-y-auto"
          >
            <ValueSetEditor
              scope={scope}
              onSuccess={(data) => {
                setIsSheetOpen(false);
                setCurrentValueSet(data);
                onValueSetChange?.(valueSetBinding(data, scope.authContext));
              }}
            />
          </SheetContent>
        </Sheet>
      </div>
      {scope.authContext === "facility" && (
        <p className="text-xs text-gray-500">{t("valueset_binding_hint")}</p>
      )}
    </div>
  );
}
                />
              </FormControl>
              <div className="space-y-1">
                <FormLabel>{t("replace_parent_in_facility")}</FormLabel>
                <FormDescription>
                  {parent && !canReplace
                    ? t("replace_parent_instance_only")
                    : t("replace_parent_in_facility_hint")}
                </FormDescription>
              </div>
            </FormItem>
          )}
        />
      </CardContent>
    </Card>
  );
}

export function ValueSetForm({
  scope,
  initialData,
  initialParent,
  onSubmit,
  isSubmitting,
  isReadOnly,
  accessControl,
}: ValueSetFormProps) {
  const { t } = useTranslation();
  const [parent, setParent] = useState<ValueSetRead | undefined>(initialParent);
  const [openRules, setOpenRules] = useState<{
    include: number | null;
    exclude: number | null;
  }>({
    include: initialData?.compose.include.length ? 0 : null,
    exclude: initialData?.compose.exclude.length ? 0 : null,
  });
  // The seeded parent always comes from the list's Instance tab, which is
  // the only place Customize is offered.
  const [parentScope, setParentScope] =
    useState<ScopedValueSet["authContext"]>("instance");
  // Lineage is create-only, and only a facility can extend another set.
  const showBasedOn = !initialData && scope.authContext === "facility";

  const conceptSchema = z.object({
    code: z.string().min(1, t("field_required")),
    display: z.string().min(1, t("valueset_verify_before_saving")),
  });
  const filterSchema = z.object({
    property: z.string().min(1, t("field_required")),
    op: z.string().min(1, t("field_required")),
    value: z.string().min(1, t("field_required")),
  });
  const ruleSchema = z.object({
    system: z.string(),
    version: z.string(),
    concept: z.array(conceptSchema).optional(),
    filter: z.array(filterSchema).optional(),
  });
  const valuesetFormSchema = z
    .object({
      name: z.string().trim().min(1, t("field_required")),
      slug: z.string().trim(),
      description: z.string(),
      status: z.enum([
        ValueSetStatus.ACTIVE,
        ValueSetStatus.DRAFT,
        ValueSetStatus.RETIRED,
        ValueSetStatus.UNKNOWN,
      ]),
      is_system_defined: z.boolean(),
      compose: z.object({
        include: z.array(ruleSchema),
        exclude: z.array(ruleSchema),
      }),
      parent: z.string().optional(),
      inherited: z.boolean(),
    })
    .superRefine((data, ctx) => {
      // These are authoring rules for a NEW slug. They do not apply to a
      // slug the server assigned: an inherited set takes its parent's
      // verbatim, and an existing set keeps its own — several system slugs
      // are longer than SLUG_MAX, and re-validating them here would make
      // those sets impossible to save.
      if (data.inherited || data.slug === initialData?.slug) return;
      if (data.slug.length < SLUG_MIN || data.slug.length > SLUG_MAX) {
        ctx.addIssue({
          code: "custom",
          path: ["slug"],
          message: t("character_count_validation", {
            min: SLUG_MIN,
            max: SLUG_MAX,
          }),
        });
      } else if (!/^[-\w]+$/.test(data.slug)) {
        ctx.addIssue({
          code: "custom",
          path: ["slug"],
          message: t("slug_format_message"),
        });
      }
    });

  const form = useForm<ValueSetFormData>({
    resolver: zodResolver(valuesetFormSchema),
    shouldFocusError: false,
    defaultValues: {
      name: initialData?.name || "",
      slug: initialData?.slug || initialParent?.slug || "",
      description: initialData?.description || "",
      status: initialData?.status || ValueSetStatus.ACTIVE,
      is_system_defined: initialData?.is_system_defined || false,
      compose: {
        include:
          initialData?.compose?.include.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
        exclude:
          initialData?.compose?.exclude.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
      },
      parent: initialParent?.id,
      // Customize defaults to replacing the parent — that is the whole
      // point of the flow; a plain extension is the opt-out.
      inherited: !!initialParent,
    },
  });

  // All fields have complete defaults above; react-hook-form's broad
  // DeepPartial return type does not reflect that runtime guarantee.
  const values = useWatch({ control: form.control }) as ValueSetFormData;
  const inherited = values.inherited;
  const pageTitle = initialData
    ? initialData.is_system_defined
      ? t("preview_value_set")
      : t("edit_value_set")
    : t("create_new_value_set");
  const issues = collectFormIssues(form.formState.errors);
  const isDirty = form.formState.isDirty;
  useNavigationPrompt(
    isDirty && !isSubmitting && !isReadOnly,
