export function ValueSetForm({
  scope,
  initialData,
  initialParent,
  onSubmit,
  isSubmitting,
  isReadOnly,
  accessControl,
}: ValueSetFormProps) {
  const { t } = useTranslation();
  const [parent, setParent] = useState<ValueSetRead | undefined>(initialParent);
  const [openRules, setOpenRules] = useState<{
    include: number | null;
    exclude: number | null;
  }>({
    include: initialData?.compose.include.length ? 0 : null,
    exclude: initialData?.compose.exclude.length ? 0 : null,
  });
  // The seeded parent always comes from the list's Instance tab, which is
  // the only place Customize is offered.
  const [parentScope, setParentScope] =
    useState<ScopedValueSet["authContext"]>("instance");
  // Lineage is create-only, and only a facility can extend another set.
  const showBasedOn = !initialData && scope.authContext === "facility";

  const conceptSchema = z.object({
    code: z.string().min(1, t("field_required")),
    display: z.string().min(1, t("valueset_verify_before_saving")),
  });
  const filterSchema = z.object({
    property: z.string().min(1, t("field_required")),
    op: z.string().min(1, t("field_required")),
    value: z.string().min(1, t("field_required")),
  });
  const ruleSchema = z.object({
    system: z.string(),
    version: z.string(),
    concept: z.array(conceptSchema).optional(),
    filter: z.array(filterSchema).optional(),
  });
  const valuesetFormSchema = z
    .object({
      name: z.string().trim().min(1, t("field_required")),
      slug: z.string().trim(),
      description: z.string(),
      status: z.enum([
        ValueSetStatus.ACTIVE,
        ValueSetStatus.DRAFT,
        ValueSetStatus.RETIRED,
        ValueSetStatus.UNKNOWN,
      ]),
      is_system_defined: z.boolean(),
      compose: z.object({
        include: z.array(ruleSchema),
        exclude: z.array(ruleSchema),
      }),
      parent: z.string().optional(),
      inherited: z.boolean(),
    })
    .superRefine((data, ctx) => {
      // These are authoring rules for a NEW slug. They do not apply to a
      // slug the server assigned: an inherited set takes its parent's
      // verbatim, and an existing set keeps its own — several system slugs
      // are longer than SLUG_MAX, and re-validating them here would make
      // those sets impossible to save.
      if (data.inherited || data.slug === initialData?.slug) return;
      if (data.slug.length < SLUG_MIN || data.slug.length > SLUG_MAX) {
        ctx.addIssue({
          code: "custom",
          path: ["slug"],
          message: t("character_count_validation", {
            min: SLUG_MIN,
            max: SLUG_MAX,
          }),
        });
      } else if (!/^[-\w]+$/.test(data.slug)) {
        ctx.addIssue({
          code: "custom",
          path: ["slug"],
          message: t("slug_format_message"),
        });
      }
    });

  const form = useForm<ValueSetFormData>({
    resolver: zodResolver(valuesetFormSchema),
    shouldFocusError: false,
    defaultValues: {
      name: initialData?.name || "",
      slug: initialData?.slug || initialParent?.slug || "",
      description: initialData?.description || "",
      status: initialData?.status || ValueSetStatus.ACTIVE,
      is_system_defined: initialData?.is_system_defined || false,
      compose: {
        include:
          initialData?.compose?.include.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
        exclude:
          initialData?.compose?.exclude.map((rule) => ({
            ...rule,
            version: rule.version ?? "",
          })) || [],
      },
      parent: initialParent?.id,
      // Customize defaults to replacing the parent — that is the whole
      // point of the flow; a plain extension is the opt-out.
      inherited: !!initialParent,
    },
  });

  // All fields have complete defaults above; react-hook-form's broad
  // DeepPartial return type does not reflect that runtime guarantee.
  const values = useWatch({ control: form.control }) as ValueSetFormData;
  const inherited = values.inherited;
  const pageTitle = initialData
    ? initialData.is_system_defined
      ? t("preview_value_set")
      : t("edit_value_set")
    : t("create_new_value_set");
  const issues = collectFormIssues(form.formState.errors);
  const isDirty = form.formState.isDirty;
  useNavigationPrompt(
    isDirty && !isSubmitting && !isReadOnly,
    t("unsaved_changes_warning"),
  );

  const focusIssue = (issue: FormIssue) => {
    const parts = issue.name.split(".");
    if (
      parts[0] === "compose" &&
      (parts[1] === "include" || parts[1] === "exclude")
    ) {
      setOpenRules((current) => ({ ...current, [parts[1]]: Number(parts[2]) }));
    }
    requestAnimationFrame(() => {
      const target = issue.name.endsWith(".display")
        ? (issue.name.replace(
            /\.display$/,
            ".code",
          ) as FieldPath<ValueSetFormData>)
        : issue.name;
      form.setFocus(target);
      // Scroll the focused control below the desktop toolbar.
      document.activeElement?.scrollIntoView({
        block: "center",
        behavior: "auto",
      });
    });
  };
  const issueLabel = (issue: FormIssue) => {
    const parts = issue.name.split(".");
    if (parts[0] !== "compose") return t(parts[0]);
    const rule = t(
      parts[1] === "include"
        ? "valueset_include_rule"
        : "valueset_exclude_rule",
      { number: Number(parts[2]) + 1 },
    );
    if (parts[3] === "concept" || parts[3] === "filter") {
      return t("valueset_issue_location", {
        rule,
        item: t(
          parts[3] === "concept"
            ? "valueset_concept_number"
            : "valueset_filter_number",
          { number: Number(parts[4]) + 1 },
        ),
      });
    }
    return rule;
  };
  const handleInvalid = (errors: FieldErrors<ValueSetFormData>) => {
    const firstIssue = collectFormIssues(errors)[0];
    if (firstIssue) focusIssue(firstIssue);
  };
  const saveButton = (
    <Button
      variant="primary"
      type="submit"
      disabled={isSubmitting || !isDirty}
      className="h-11 lg:h-9"
    >
      <Save className="size-4" />
      {isSubmitting ? t("saving") : t("save_valueset")}
    </Button>
  );

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit((data) => {
          if (!isReadOnly && !isSubmitting) onSubmit(data);
        }, handleInvalid)}
        className="space-y-5"
      >
        <div className="-mx-4 -mt-4 space-y-3 border-b border-gray-200 bg-white/95 px-4 py-3 backdrop-blur-sm sm:-mx-6 sm:-mt-6 sm:px-6 lg:sticky lg:top-0 lg:z-20 lg:-mx-8 lg:px-8">
          <Button
            type="button"
            variant="outline"
            size="xs"
            disabled={isSubmitting}
            onClick={() => goBack(scope.basePath)}
          >
            <ArrowLeft className="size-4" />
            {t("back")}
          </Button>

          <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex min-w-0 flex-wrap items-center gap-2">
              <h1 className="text-3xl leading-9 font-bold tracking-tight text-gray-950">
                {pageTitle}
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { navigate, useQueryParams } from "raviger";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { FormSkeleton } from "@/components/Common/SkeletonLoading";

import {
  ValueSetBase,
  ValueSetCreate,
  ValueSetRead,
  ValueSetScope,
  ValueSetUpdate,
  scopeCreateContext,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

import { useCanWriteValueSet } from "./useCanWriteValueSet";
import { ValueSetForm, ValueSetFormSubmit } from "./ValueSetForm";
import { ValueSetOrganizationsField } from "./ValueSetOrganizationsField";

interface ValueSetEditorProps {
  id?: string; // If provided, we're editing an existing valueset
  scope: ValueSetScope;
  /** Overrides the default post-save navigation (an inline sheet closes
   *  itself instead of leaving the page). */
  onSuccess?: (data: ValueSetRead) => void;
}

function normalizeValueSetPayload(data: ValueSetBase): ValueSetBase {
  return {
    ...data,
    compose: {
      include: data.compose.include.map((rule) => ({
        ...rule,
        version: rule.version?.trim() || null,
      })),
      exclude: data.compose.exclude.map((rule) => ({
        ...rule,
        version: rule.version?.trim() || null,
      })),
    },
  };
}

export function ValueSetEditor({ id, scope, onSuccess }: ValueSetEditorProps) {
  const queryClient = useQueryClient();
  const { t } = useTranslation();
  // Hold the form until permissions are known — otherwise a facility mount
  // renders editable, then snaps to read-only when the facility resolves.
  const { canWrite, isLoading: isPermissionLoading } =
    useCanWriteValueSet(scope);
  // `?parent=` is how the list's Customize action seeds a new facility set.
  const [{ parent: initialParentId }] = useQueryParams<{ parent?: string }>();

  // Fetch existing valueset if we're editing
  const { data: existingValueset, isLoading } = useQuery({
    queryKey: ["valueset", id],
    queryFn: query(valueSetApi.get, {
      pathParams: { id: id! },
    }),
    enabled: !!id,
  });

  const { data: initialParent, isLoading: isLoadingParent } = useQuery({
    queryKey: ["valueset", initialParentId],
    queryFn: query(valueSetApi.get, {
      pathParams: { id: initialParentId ?? "" },
    }),
    enabled: !id && !!initialParentId,
  });

  // Create mutation
  const createMutation = useMutation({
    mutationFn: mutate(valueSetApi.create),
    onSuccess: (data: ValueSetRead) => {
      toast.success(t("valueset_created"));
      queryClient.invalidateQueries({ queryKey: ["valuesets"] });
      if (onSuccess) {
        onSuccess(data);
        return;
      }
      // A facility set is invisible to everyone but superusers until it has
      // departments, and those are edited on the edit page — land there.
      navigate(
        scope.authContext === "facility"
          ? `${scope.basePath}/${data.id}/edit`
          : scope.basePath,
      );
    },
  });

  // Update mutation
  const updateMutation = useMutation({
    mutationFn: mutate(valueSetApi.update, {
      pathParams: { id: id! },
    }),
    onSuccess: (data: ValueSetRead) => {
      toast.success(t("valueset_updated"));
      queryClient.removeQueries({ queryKey: ["valueset", id] });
      queryClient.invalidateQueries({ queryKey: ["valuesets"] });
      if (onSuccess) {
        onSuccess(data);
        return;
      }
      navigate(scope.basePath);
    },
  });

  const handleSubmit = ({ parent, inherited, ...data }: ValueSetFormSubmit) => {
    const payload = normalizeValueSetPayload(data);

    if (id) {
      // Keyed on `id`, not on the fetched object: a failed GET must not
      // turn an edit into a create, which would file a duplicate set.
      if (!existingValueset) {
        return;
      }
      const updateData: ValueSetUpdate = {
        ...payload,
        id: existingValueset.id,
      };
      updateMutation.mutate(updateData);
    } else {
      const createData: ValueSetCreate = {
        ...payload,
        ...scopeCreateContext(scope),
        parent,
        inherited,
      };
      createMutation.mutate(createData);
    }
  };

  return (
    <div className="mx-auto max-w-5xl px-4 py-4 sm:px-6 sm:py-6 lg:px-8">
      {(id && isLoading) ||
      (initialParentId && isLoadingParent) ||
      isPermissionLoading ? (
        <FormSkeleton rows={10} />
      ) : (
        <ValueSetForm
          scope={scope}
          initialData={existingValueset}
          initialParent={initialParent}
          onSubmit={handleSubmit}
          isSubmitting={createMutation.isPending || updateMutation.isPending}
          isReadOnly={!canWrite}
          accessControl={
            id && scope.authContext === "facility" ? (
              <ValueSetOrganizationsField
                facilityId={scope.facilityId}
                valuesetId={id}
                canWrite={canWrite}
              />
            ) : undefined
          }
        />
      )}
    </div>
  );
}

