      >
        <div className="-mx-4 -mt-4 space-y-3 border-b border-gray-200 bg-white/95 px-4 py-3 backdrop-blur-sm sm:-mx-6 sm:-mt-6 sm:px-6 lg:sticky lg:top-0 lg:z-20 lg:-mx-8 lg:px-8">
          <Button
            type="button"
            variant="outline"
            size="xs"
            disabled={isSubmitting}
            onClick={() => goBack(scope.basePath)}
          >
            <ArrowLeft className="size-4" />
            {t("back")}
          </Button>

          <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex min-w-0 flex-wrap items-center gap-2">
              <h1 className="text-3xl leading-9 font-bold tracking-tight text-gray-950">
                {pageTitle}
              </h1>
              <Badge variant="outline" className="uppercase">
                {t(scope.authContext)}
              </Badge>
              {isReadOnly && (
                <Badge variant="secondary">{t("read_only")}</Badge>
              )}
            </div>

            <div className="flex flex-wrap items-center gap-2">
              <ValueSetPreview
                valueset={values}
                trigger={
                  <Button type="button" variant="outline_primary">
                    <Eye className="size-4" />
                    {t("valueset_preview")}
                  </Button>
                }
              />
              <Button
                variant="outline"
                disabled={isSubmitting}
                type="button"
                onClick={() => goBack(scope.basePath)}
              >
                {t("cancel")}
              </Button>
              {!isReadOnly && (
                <div className="hidden lg:block">{saveButton}</div>
              )}
            </div>
          </div>
        </div>

        {form.formState.submitCount > 0 && issues.length > 0 && (
          <Alert variant="destructive" className="border-red-200">
            <AlertCircle />
            <AlertTitle>{t("valueset_fix_errors")}</AlertTitle>
            <AlertDescription>
              <ul className="space-y-1">
                {issues.map((issue) => (
                  <li key={issue.name}>
                    <button
                      type="button"
                      className="cursor-pointer text-left underline underline-offset-2"
                      onClick={() => focusIssue(issue)}
                    >
                      {issueLabel(issue)}: {issue.message}
                    </button>
                  </li>
                ))}
              </ul>
            </AlertDescription>
          </Alert>
        )}

        <div className="space-y-7">
          <div className="min-w-0 space-y-7">
            <section className="space-y-4 border-b border-gray-200 pb-6">
              <h2 className="text-base font-semibold tracking-tight text-gray-900">
                {t("basic_information")}
              </h2>
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)_180px]">
                <FormField
                  control={form.control}
                  name="name"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("name")}</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          disabled={isReadOnly || isSubmitting}
                          className="h-12 md:h-10"
                          placeholder={t("valueset_name_placeholder")}
                          onChange={(event) => {
                            field.onChange(event);
                            if (
                              initialData ||
                              form.getValues("inherited") ||
                              form.formState.dirtyFields.slug
                            ) {
                              return;
                            }
                            form.setValue(
                              "slug",
                              generateSlug(event.target.value, SLUG_MAX),
                              {
                                shouldValidate: true,
                                shouldDirty: false,
                              },
                            );
                          }}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="slug"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("slug")}</FormLabel>
                      <FormControl>
                        {/* Locked on the element, not the Controller: a
                            disabled Controller drops its value from submitted
                            data, but inherited slugs still reach the backend. */}
                        <Input
                          {...field}
                          disabled={isReadOnly || inherited || isSubmitting}
                          className="h-12 font-mono text-sm md:h-10"
                          onChange={(event) => {
                            const sanitizedValue = event.target.value
                              .toLowerCase()
                              .replace(/[^a-z0-9_-]/g, "");
                            form.setValue("slug", sanitizedValue, {
                              shouldValidate: true,
                              shouldDirty: true,
                            });
                          }}
                        />
                      </FormControl>
                      <FormMessage />
                      <FormDescription>
                        {inherited
                          ? t("replace_parent_slug_locked")
                          : t("slug_format_message")}
                      </FormDescription>
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem className="order-last sm:col-span-2 lg:col-span-3">
                      <FormLabel>
                        {t("description")}{" "}
                        <span className="font-normal text-gray-500">
                          ({t("optional")})
                        </span>
                      </FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          disabled={isReadOnly || isSubmitting}
                          className="min-h-16 resize-y py-2"
                          rows={2}
                          placeholder={t("valueset_description_placeholder")}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="status"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("status")}</FormLabel>
                      <Select
                        onValueChange={field.onChange}
                        value={field.value}
                        disabled={isReadOnly || isSubmitting}
                      >
                        <FormControl>
                          <SelectTrigger
                            ref={field.ref}
                            className="w-full data-[size=default]:h-12 md:data-[size=default]:h-10"
                          >
                            <SelectValue placeholder={t("select_status")} />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {valuesOf(ValueSetStatus).map((status) => (
                            <SelectItem key={status} value={status}>
                              {t(status)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
            </section>

            {accessControl && (
              <Card className="shadow-none">
                <CardContent className="p-4 sm:p-5">
                  {accessControl}
                </CardContent>
              </Card>
            )}

            {showBasedOn && (
              <BasedOnFields
                facilityId={scope.facilityId}
                form={form}
                parent={parent}
                parentScope={parentScope}
                onParentChange={(next, nextScope) => {
                  setParent(next);
                  setParentScope(nextScope);
                }}
                disabled={isReadOnly || isSubmitting}
              />
            )}

            <section className="space-y-5">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                  <Layers3 aria-hidden className="size-4 text-gray-500" />
                  <h2 className="text-xl font-semibold tracking-tight text-gray-900">
                    {t("definition")}
                  </h2>
                </div>
                {!isReadOnly && (
                  <p role="status" className="text-sm text-gray-500">
                    {t(
                      isDirty
                        ? "valueset_unsaved_changes"
                        : "no_changes_to_save",
                    )}
                  </p>
                )}
              </div>
              <div className="grid items-start gap-7">
                <RuleFields
                  type="include"
                  form={form}
                  disabled={isReadOnly || isSubmitting}
                  openIndex={openRules.include}
                  onOpenIndexChange={(include) =>
                    setOpenRules((current) => ({ ...current, include }))
                  }
                />
                <RuleFields
                  type="exclude"
                  form={form}
                  disabled={isReadOnly || isSubmitting}
                  openIndex={openRules.exclude}
                  onOpenIndexChange={(exclude) =>
                    setOpenRules((current) => ({ ...current, exclude }))
                  }
                />
              </div>
            </section>
          </div>

          {isReadOnly && (
            <div className="rounded-lg border border-gray-200 bg-gray-100 p-3 text-sm text-gray-700">
              {t(
                initialData?.is_system_defined
                  ? "saving_is_disabled_for_system_valuesets"
                  : "no_permission_to_edit_valueset",
              )}
import * as React from "react";

import { Slot } from "@radix-ui/react-slot";
import { type VariantProps, cva } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-hidden focus-visible:ring-1 focus-visible:ring-gray-950 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 dark:focus-visible:ring-gray-300 aria-invalid:border-red-500 aria-invalid:ring-red-500/20",
  {
    variants: {
      variant: {
        default:
          "bg-gray-900 text-gray-50 shadow-sm hover:bg-gray-900/90 dark:bg-gray-50 dark:text-gray-900 dark:hover:bg-gray-50/90",
        destructive:
          "bg-red-500 text-gray-50 shadow-xs hover:bg-red-500/90 dark:bg-red-900 dark:text-gray-50 dark:hover:bg-red-900/90",
        outline:
          "border border-gray-400 bg-white shadow-sm hover:bg-gray-100 hover:text-gray-900 dark:border-gray-800 dark:bg-gray-950 dark:hover:bg-gray-800 dark:hover:text-gray-50",
        primary:
          "bg-primary-700 text-white shadow-sm hover:bg-primary-700/90 dark:bg-primary-100 dark:text-primary-900 dark:hover:bg-primary-100/90",
        secondary:
          "bg-gray-100 text-gray-900 shadow-xs hover:bg-gray-100/80 dark:bg-gray-800 dark:text-gray-50 dark:hover:bg-gray-800/80",
        ghost:
          "hover:bg-gray-100 hover:text-gray-900 dark:hover:bg-gray-800 dark:hover:text-gray-50",
        link: "text-gray-900 underline-offset-4 hover:underline dark:text-gray-50",
        outline_primary:
          "border border-primary-700 text-primary-700 bg-white shadow-xs hover:bg-primary-700 hover:text-white dark:border-primary-700 dark:bg-primary-700 dark:text-white",
        primary_gradient:
          "text-white border border-primary-900 rounded-lg font-medium relative overflow-hidden bg-linear-to-b from-primary-700 to-primary-800 hover:from-primary-800 hover:to-primary-900 shadow-lg",
        white:
          "bg-white border border-secondary-400 text-gray-900 shadow-xs hover:bg-gray-100 hover:text-gray-900 dark:bg-gray-800 dark:text-gray-50 dark:hover:bg-gray-800/80",
        warning:
          "bg-warning-100 text-warning-900 border border-warning-300 shadow-xs hover:bg-warning-100/80 dark:bg-warning-900 dark:text-warning-50 dark:hover:bg-warning-900/80",
        alert:
          "bg-alert-100 text-alert-900 border border-alert-300 shadow-xs hover:bg-alert-100/80 dark:bg-alert-900 dark:text-alert-50 dark:hover:bg-alert-900/80",
      },
      size: {
        default: "h-9 px-4 py-2",
        xs: "h-6 rounded-md px-2 text-xs",
        sm: "h-8 rounded-md px-3 text-xs",
        md: "h-9 rounded-md px-4 text-sm",
        lg: "h-10 rounded-md px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "primary",
      size: "default",
    },
  },
);

export type ButtonVariant =
  | "primary"
  | "outline"
  | "secondary"
  | "destructive"
  | "primary_gradient"
  | "ghost"
  | "link"
  | "white"
  | "alert"
  | "warning"
  | "outline_primary";
export type ButtonSize = "default" | "xs" | "sm" | "md" | "lg" | "icon";

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}
Button.displayName = "Button";

export { Button, buttonVariants };

