                {t("basic_information")}
              </h2>
              <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)_180px]">
                <FormField
                  control={form.control}
                  name="name"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("name")}</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          disabled={isReadOnly || isSubmitting}
                          className="h-12 md:h-10"
                          placeholder={t("valueset_name_placeholder")}
                          onChange={(event) => {
                            field.onChange(event);
                            if (
                              initialData ||
                              form.getValues("inherited") ||
                              form.formState.dirtyFields.slug
                            ) {
                              return;
                            }
                            form.setValue(
                              "slug",
                              generateSlug(event.target.value, SLUG_MAX),
                              {
                                shouldValidate: true,
                                shouldDirty: false,
                              },
                            );
                          }}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="slug"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("slug")}</FormLabel>
                      <FormControl>
                        {/* Locked on the element, not the Controller: a
                            disabled Controller drops its value from submitted
                            data, but inherited slugs still reach the backend. */}
                        <Input
                          {...field}
                          disabled={isReadOnly || inherited || isSubmitting}
                          className="h-12 font-mono text-sm md:h-10"
                          onChange={(event) => {
                            const sanitizedValue = event.target.value
                              .toLowerCase()
                              .replace(/[^a-z0-9_-]/g, "");
                            form.setValue("slug", sanitizedValue, {
                              shouldValidate: true,
                              shouldDirty: true,
                            });
                          }}
                        />
                      </FormControl>
                      <FormMessage />
                      <FormDescription>
                        {inherited
                          ? t("replace_parent_slug_locked")
                          : t("slug_format_message")}
                      </FormDescription>
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem className="order-last sm:col-span-2 lg:col-span-3">
                      <FormLabel>
                        {t("description")}{" "}
                        <span className="font-normal text-gray-500">
                          ({t("optional")})
                        </span>
                      </FormLabel>
                      <FormControl>
                        <Textarea
                          {...field}
                          disabled={isReadOnly || isSubmitting}
                          className="min-h-16 resize-y py-2"
                          rows={2}
                          placeholder={t("valueset_description_placeholder")}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="status"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel aria-required>{t("status")}</FormLabel>
                      <Select
                        onValueChange={field.onChange}
                        value={field.value}
                        disabled={isReadOnly || isSubmitting}
                      >
                        <FormControl>
                          <SelectTrigger
                            ref={field.ref}
                            className="w-full data-[size=default]:h-12 md:data-[size=default]:h-10"
                          >
                            <SelectValue placeholder={t("select_status")} />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          {valuesOf(ValueSetStatus).map((status) => (
                            <SelectItem key={status} value={status}>
                              {t(status)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
            </section>

            {accessControl && (
              <Card className="shadow-none">
                <CardContent className="p-4 sm:p-5">
                  {accessControl}
                </CardContent>
              </Card>
            )}

            {showBasedOn && (
              <BasedOnFields
                facilityId={scope.facilityId}
                form={form}
                parent={parent}
                parentScope={parentScope}
                onParentChange={(next, nextScope) => {
                  setParent(next);
                  setParentScope(nextScope);
                }}
                disabled={isReadOnly || isSubmitting}
              />
            )}

            <section className="space-y-5">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                  <Layers3 aria-hidden className="size-4 text-gray-500" />
                  <h2 className="text-xl font-semibold tracking-tight text-gray-900">
                    {t("definition")}
                  </h2>
                </div>
                {!isReadOnly && (
                  <p role="status" className="text-sm text-gray-500">
                    {t(
                      isDirty
                        ? "valueset_unsaved_changes"
                        : "no_changes_to_save",
                    )}
                  </p>
                )}
              </div>
              <div className="grid items-start gap-7">
                <RuleFields
                  type="include"
                  form={form}
                  disabled={isReadOnly || isSubmitting}
                  openIndex={openRules.include}
                  onOpenIndexChange={(include) =>
                    setOpenRules((current) => ({ ...current, include }))
                  }
                />
                <RuleFields
                  type="exclude"
                  form={form}
                  disabled={isReadOnly || isSubmitting}
                  openIndex={openRules.exclude}
                  onOpenIndexChange={(exclude) =>
                    setOpenRules((current) => ({ ...current, exclude }))
                  }
                />
              </div>
            </section>
          </div>

          {isReadOnly && (
            <div className="rounded-lg border border-gray-200 bg-gray-100 p-3 text-sm text-gray-700">
              {t(
                initialData?.is_system_defined
                  ? "saving_is_disabled_for_system_valuesets"
                  : "no_permission_to_edit_valueset",
              )}
