  slug: string;
  facility?: string;
}

export interface ExpandSlugResponse {
  valueset: ValueSetRead;
  results: CodeConceptMinimal[];
}

export interface ValueSetConfig {
  slug?: string;
  external_id?: string;
interface FormIssue {
  name: FieldPath<ValueSetFormData>;
  message: string;
}

function collectFormIssues(errors: unknown, path = ""): FormIssue[] {
  if (!errors || typeof errors !== "object") return [];
