import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { navigate, useQueryParams } from "raviger";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { FormSkeleton } from "@/components/Common/SkeletonLoading";

import {
  ValueSetBase,
  ValueSetCreate,
  ValueSetRead,
  ValueSetScope,
  ValueSetUpdate,
  scopeCreateContext,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

import { useCanWriteValueSet } from "./useCanWriteValueSet";
import {
  ValueSetForm,
  ValueSetFormSubmit,
  type ValueSetFormState,
} from "./ValueSetForm";
import { ValueSetOrganizationsField } from "./ValueSetOrganizationsField";

interface ValueSetEditorProps {
  id?: string; // If provided, we're editing an existing valueset
  scope: ValueSetScope;
  /** Overrides the default post-save navigation (an inline sheet closes
   *  itself instead of leaving the page). */
  onSuccess?: (data: ValueSetRead) => void;
  /** Lets an embedded editor close its host instead of navigating away. */
  onCancel?: () => void;
  /** Reports whether closing the host could discard an edit or active save. */
  onStateChange?: (state: ValueSetFormState) => void;
}

function normalizeValueSetPayload(data: ValueSetBase): ValueSetBase {
  return {
    ...data,
    compose: {
      include: data.compose.include.map((rule) => ({
        ...rule,
        version: rule.version?.trim() || null,
      })),
      exclude: data.compose.exclude.map((rule) => ({
        ...rule,
        version: rule.version?.trim() || null,
      })),
    },
  };
}

export function ValueSetEditor({
  id,
  scope,
  onSuccess,
  onCancel,
  onStateChange,
}: ValueSetEditorProps) {
  const queryClient = useQueryClient();
  const { t } = useTranslation();
  // Hold the form until permissions are known — otherwise a facility mount
  // renders editable, then snaps to read-only when the facility resolves.
  const { canWrite, isLoading: isPermissionLoading } =
    useCanWriteValueSet(scope);
  // `?parent=` is how the list's Customize action seeds a new facility set.
  const [{ parent: initialParentId }] = useQueryParams<{ parent?: string }>();

  // Fetch existing valueset if we're editing
  const { data: existingValueset, isLoading } = useQuery({
    queryKey: ["valueset", id],
    queryFn: query(valueSetApi.get, {
      pathParams: { id: id! },
    }),
    enabled: !!id,
  });

  const { data: initialParent, isLoading: isLoadingParent } = useQuery({
    queryKey: ["valueset", initialParentId],
    queryFn: query(valueSetApi.get, {
      pathParams: { id: initialParentId ?? "" },
    }),
    enabled: !id && !!initialParentId,
  });

  // Create mutation
  const createMutation = useMutation({
    mutationFn: mutate(valueSetApi.create),
    onSuccess: (data: ValueSetRead) => {
      toast.success(t("valueset_created"));
      queryClient.invalidateQueries({ queryKey: ["valuesets"] });
      if (onSuccess) {
        onSuccess(data);
        return;
      }
      // A facility set is invisible to everyone but superusers until it has
      // departments, and those are edited on the edit page — land there.
      navigate(
        scope.authContext === "facility"
          ? `${scope.basePath}/${data.id}/edit`
          : scope.basePath,
      );
    },
  });

  // Update mutation
  const updateMutation = useMutation({
    mutationFn: mutate(valueSetApi.update, {
      pathParams: { id: id! },
    }),
    onSuccess: (data: ValueSetRead) => {
      toast.success(t("valueset_updated"));
      queryClient.removeQueries({ queryKey: ["valueset", id] });
      queryClient.invalidateQueries({ queryKey: ["valuesets"] });
      if (onSuccess) {
        onSuccess(data);
        return;
      }
      navigate(scope.basePath);
    },
  });

  const handleSubmit = ({ parent, inherited, ...data }: ValueSetFormSubmit) => {
    const payload = normalizeValueSetPayload(data);

    if (id) {
      // Keyed on `id`, not on the fetched object: a failed GET must not
      // turn an edit into a create, which would file a duplicate set.
      if (!existingValueset) {
        return;
      }
      const updateData: ValueSetUpdate = {
        ...payload,
        id: existingValueset.id,
        // Slugs are stable references, not editable metadata. Preserve the
        // fetched identifier even if form state is changed programmatically.
        slug: existingValueset.slug,
      };
      updateMutation.mutate(updateData);
    } else {
      const createData: ValueSetCreate = {
        ...payload,
        ...scopeCreateContext(scope),
        parent,
        inherited,
      };
      createMutation.mutate(createData);
    }
  };

  return (
    <div className="mx-auto max-w-5xl px-4 py-4 sm:px-6 sm:py-6 lg:px-8">
      {(id && isLoading) ||
      (initialParentId && isLoadingParent) ||
      isPermissionLoading ? (
        <FormSkeleton rows={10} />
      ) : (
        <ValueSetForm
          scope={scope}
          initialData={existingValueset}
          initialParent={initialParent}
          onSubmit={handleSubmit}
          onCancel={onCancel}
          onStateChange={onStateChange}
          isSubmitting={createMutation.isPending || updateMutation.isPending}
          isReadOnly={!canWrite}
          accessControl={
            id && scope.authContext === "facility" ? (
              <ValueSetOrganizationsField
                facilityId={scope.facilityId}
                valuesetId={id}
                canWrite={canWrite}
              />
            ) : undefined
          }
        />
      )}
    </div>
  );
}
import { useState } from "react";
import { useTranslation } from "react-i18next";

import Autocomplete from "@/components/ui/autocomplete";

import { ValueSetRead } from "@/types/valueSet/valueSet";
import { mergeAutocompleteOptions } from "@/Utils/utils";

import {
  ScopedValueSet,
  scopedOptionLabel,
  useScopedValueSets,
} from "./useScopedValueSets";

interface ValueSetParentPickerProps {
  facilityId: string;
  /** The current parent — may come from outside the loaded pages (e.g. a
   *  `?parent=` deep link), so it is merged into the options by identity. */
  value?: ValueSetRead;
  onChange: (parent: ScopedValueSet | undefined) => void;
  disabled?: boolean;
  id?: string;
  "aria-labelledby"?: string;
}

/**
 * Picks the value set a new facility set extends: the instance sets plus
 * this facility's own, each labelled with where it lives so two sets that
 * share a name (an instance set and a facility override of it) stay
 * distinguishable.
 */
export function ValueSetParentPicker({
  facilityId,
  value,
  onChange,
  disabled,
  ...ariaProps
}: ValueSetParentPickerProps) {
  const { t } = useTranslation();
  const [search, setSearch] = useState("");
  const { options, isFetching } = useScopedValueSets({ facilityId, search });

  const autocompleteOptions = mergeAutocompleteOptions(
    options.map((option) => ({
      label: scopedOptionLabel(option, t),
      value: option.valueset.id,
    })),
    // The seeded parent (`?parent=`) may sit outside the loaded page, so it
    // is merged in by identity — and carries no scope suffix, since only
    // the two lists above establish where a set lives.
    value ? { label: value.name, value: value.id } : undefined,
  );

  const handleChange = (id: string) => {
    if (!id) {
      onChange(undefined);
      return;
    }
    const picked = options.find((option) => option.valueset.id === id);
    // Re-picking the merged-in current parent finds nothing in `options`;
    // keeping the selection beats silently clearing it.
    if (picked || id !== value?.id) {
      onChange(picked);
    }
  };

  return (
    <Autocomplete
      {...ariaProps}
      options={autocompleteOptions}
      value={value?.id ?? ""}
      onChange={handleChange}
      onSearch={setSearch}
      isLoading={isFetching}
      disabled={disabled}
      placeholder={t("none")}
      noOptionsMessage={t("no_valuesets_found")}
    />
  );
}
import { useQuery } from "@tanstack/react-query";
import { TFunction } from "i18next";

import {
  ValueSetAuthContext,
  ValueSetRead,
  ValueSetStatus,
} from "@/types/valueSet/valueSet";
import valueSetApi from "@/types/valueSet/valueSetApi";
import query from "@/Utils/request/query";

export interface ScopedValueSet {
  valueset: ValueSetRead;
  /** Which list the set came from. `ValueSetReadSpec` does not return
   *  `auth_context`, so this is the only scope signal the UI has. */
  authContext: Extract<ValueSetAuthContext, "instance" | "facility">;
}

/** Where a value set lives, as a label. Only ever shown where the two
 *  lists are merged — an instance set and a facility override of it
 *  usually share a name. */
export function scopeLabel(
  authContext: ScopedValueSet["authContext"],
  t: TFunction,
): string {
  return t(authContext === "facility" ? "this_facility" : "instance");
}

/** `Name (This facility)` — the merged-list option label. */
export function scopedOptionLabel(
  { valueset, authContext }: ScopedValueSet,
  t: TFunction,
): string {
  return `${valueset.name} (${scopeLabel(authContext, t)})`;
}

const PAGE = 50;

/**
 * Active value sets a picker inside `facilityId` (or the admin area, when
 * undefined) may choose from: the instance-level sets, plus — inside a
 * facility — that facility's own sets, listed first. Two requests because
 * the list endpoint filters by either `auth_context` or `facility` and its
 * read spec carries neither back.
 */
export function useScopedValueSets({
  facilityId,
  search,
}: {
  facilityId?: string;
  search: string;
}): { options: ScopedValueSet[]; isFetching: boolean } {
  const params = {
    name: search || undefined,
    status: ValueSetStatus.ACTIVE,
    limit: PAGE,
  };

  const instance = useQuery({
    queryKey: ["valuesets", "scoped", "instance", search],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: { ...params, auth_context: "instance" },
    }),
  });

  const facility = useQuery({
    queryKey: ["valuesets", "scoped", "facility", facilityId, search],
    queryFn: query.debounced(valueSetApi.list, {
      queryParams: { ...params, facility: facilityId },
    }),
    enabled: !!facilityId,
  });

  const options: ScopedValueSet[] = [
    ...(facility.data?.results ?? []).map((valueset) => ({
      valueset,
      authContext: "facility" as const,
    })),
    ...(instance.data?.results ?? []).map((valueset) => ({
      valueset,
      authContext: "instance" as const,
    })),
  ];

  return {
    options,
    isFetching: instance.isFetching || facility.isFetching,
  };
}
