    .superRefine((rule, ctx) => {
      if (rule.concept?.length && rule.filter?.length) {
        ctx.addIssue({
          code: "custom",
          path: ["filter", 0, "property"],
          message: t("valueset_rule_mode_hint"),
        });
      }
    });
  const valuesetFormSchema = z
