      version: "",
      concept: [],
      filter: [],
    });
    onOpenIndexChange(nextIndex);
  };

  const removeRule = (index: number) => {
    setRemovedRule({
      index,
      rule: structuredClone(form.getValues(`compose.${type}.${index}`)),
    });
    remove(index);
    onOpenIndexChange(
      fields.length <= 1
        ? null
        : openIndex === index
